window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-102"]=[{"id":"set2-36KjqGEq","fingerprint":"f50d999b45e44230","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce definește 'zona neutră' sau 'culoarul muscular' în contextul poziționării dinților pe arcade?","options":[{"id":"A","text":"Spațiul creat de un obicei vicios, precum interpunerea unui instrument muzical."},{"id":"B","text":"Aliniamentul rezultat exclusiv în urma contactelor proximale dintre dinți."},{"id":"C","text":"Poziția în care forțele exercitate de musculatura internă (linguală) și cea externă (oro-facială) sunt în echilibru."},{"id":"D","text":"Spatiul determinat de fortele de intruzie din timpul masticatiei."},{"id":"E","text":"Rezultatul deplasărilor verticale și vestibulo-orale ale dintelui în timpul masticației."}],"correct":["C"],"pages":[175],"source":"set-2"},{"id":"set2-HuV716xZ","fingerprint":"268c8812cbe9c6be","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care dintre următoarele structuri musculare alcătuiesc unitatea funcțională denumită 'mecanism buccinator'?","options":[{"id":"A","text":"Mușchii constrictori superiori faringieni, mușchii buccinatori și mușchii orbiculari ai buzelor."},{"id":"B","text":"Mușchii constrictori superiori faringieni, mușchii buccinatori și musculatura limbii."},{"id":"C","text":"Spatiul determinat de fortele de intruzie din timpul masticatiei."},{"id":"D","text":"Mușchii buccinatori, mușchii orbiculari ai buzelor și musculatura limbii."},{"id":"E","text":"Doar mușchii buccinatori și mușchii orbiculari ai buzelor."}],"correct":["A"],"pages":[175],"source":"set-2"},{"id":"set2-AN6bHue5","fingerprint":"d9b368123341fd77","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce consecință poate avea un obicei oral precum utilizarea frecventă a unui instrument de suflat (de exemplu, clarinetul)?","options":[{"id":"A","text":"Spatiul determinat de fortele de intruzie din timpul masticatiei."},{"id":"B","text":"Intruzia dinților frontali mandibulari."},{"id":"C","text":"Mezializarea continuă a dinților frontali."},{"id":"D","text":"Abraziunea accentuată a suprafețelor meziale și distale."},{"id":"E","text":"Vestibularizarea dinților frontali maxilari."}],"correct":["E"],"pages":[175],"source":"set-2"},{"id":"set2-Bl4s-5Bu","fingerprint":"3ef2e0e6e2744120","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt afirmațiile corecte cu privire la forțele care acționează asupra suprafețelor meziale și distale ale dinților?","options":[{"id":"A","text":"Mezializarea continuă a dinților este determinată de răspunsul funcțional al osului alveolar și al țesuturilor parodontale."},{"id":"B","text":"Forțele din masticație duc la abrazarea suprafețelor dentare meziale și distale."},{"id":"C","text":"Forțele musculare din 'mecanismul buccinator' sunt singurele responsabile pentru contactele proximale."},{"id":"D","text":"Contactele proximale dintre dinți contribuie la alinierea acestora pe arcade."},{"id":"E","text":"Forțele de intruzie din timpul masticației sunt cele care delimitează 'culoarul muscular'."}],"correct":["A","B","D"],"pages":[175],"source":"set-2"},{"id":"set2-NRieMquz","fingerprint":"ba563ab251168192","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care este principiul fundamental care determină poziția finală a dinților pe arcade după erupție?","options":[{"id":"A","text":"Orientarea într-o poziție în care forțele opuse sunt în echilibru."},{"id":"B","text":"Răspunsul funcțional al osului alveolar, independent de alte forțe."},{"id":"C","text":"Exclusiv acțiunea morfogenetică a musculaturii limbii."},{"id":"D","text":"Spatiul determinat de fortele de intruzie din timpul masticatiei."},{"id":"E","text":"Prezența sau absența obiceiurilor orale vicioase."}],"correct":["A"],"pages":[175],"source":"set-2"},{"id":"set2-F1iln7lK","fingerprint":"4f0f8130fd598f65","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt afirmațiile corecte referitoare la forțele și mișcările dentare care contribuie la alinierea pe arcadă?","options":[{"id":"A","text":"Forțele masticatorii imprimă dintelui exclusiv o deplasare verticală în alveolă (intruzie)."},{"id":"B","text":"Contactele proximale dintre dinți contribuie la alinierea acestora pe arcade."},{"id":"C","text":"Migrarea dentară în situația întreruperii continuității arcadei se produce doar sub formă de translație."},{"id":"D","text":"Contactul ocluzal previne migrarea verticală a dinților, precum extruzia și egresiunea."},{"id":"E","text":"Mezializarea dinților contribuie la menținerea contactului interdentar pe măsură ce apare abraziunea."}],"correct":["B","D","E"],"pages":[176],"source":"set-2"},{"id":"set2-cVfQky-4","fingerprint":"425375406504b2a4","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce definește corect planul de ocluzie?","options":[{"id":"A","text":"O linie imaginară ce trece prin cuspizii vestibulari și marginile incizale ale dinților mandibulari, extinsă la un plan ce include și vârfurile cuspizilor linguali."},{"id":"B","text":"Triunghiul delimitat de latura triunghiului Bonwill și planul de ocluzie, descris de Balkwill."},{"id":"C","text":"Curbura rezultată din poziționarea dinților maxilari, care sunt toți înclinați spre mezial."},{"id":"D","text":"Suprafața dentară dintre vârfurile cuspizilor vestibulari și orali care suportă forțele de masticație."},{"id":"E","text":"Un plan perfect plat care permite contacte funcționale simultane în toate zonele arcadei."}],"correct":["A"],"pages":[176],"source":"set-2"},{"id":"set2-Gh0_ftiA","fingerprint":"c439db3690bf345c","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt caracteristicile corecte ale curbelor de ocluzie sagitală (Spee) și transversală (Wilson/Monson)?","options":[{"id":"A","text":"Curba transversală de ocluzie (Wilson) este convexă la maxilar și se observă la examinarea arcadelor din zona frontală."},{"id":"B","text":"Ambele curbe de ocluzie sunt rezultatul alinierii dinților pe un plan ocluzal perfect neted."},{"id":"C","text":"Curba sagitală de ocluzie (Spee) este concavă la mandibulă și se observă examinând arcadele din normă laterală."},{"id":"D","text":"Curba transversală de ocluzie (Wilson) este determinată de înclinarea mezială a dinților posteriori mandibulari."},{"id":"E","text":"Curba sagitală de ocluzie (Spee) este convexă la mandibulă."}],"correct":["A","C"],"pages":[176],"source":"set-2"},{"id":"set2-G_qBmjwU","fingerprint":"55f8eb748d55f65e","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce reprezintă tabla ocluzală?","options":[{"id":"A","text":"Include doar suprafețele ocluzale ale dinților anteriori."},{"id":"B","text":"Funcția sa principală este de a preveni migrarea verticală a dinților (extruzia)."},{"id":"C","text":"Este un sinonim pentru planul de ocluzie."},{"id":"D","text":"Aria dentară cuprinsă între vârfurile cuspizilor vestibulari și orali ale dinților posteriori."},{"id":"E","text":"Se referă la totalitatea contactelor proximale dintre dinți."}],"correct":["D"],"pages":[176],"source":"set-2"},{"id":"set2-i0Kgbvqb","fingerprint":"dca9b5e987e6c28c","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Conform teoriei sferei elaborată de Monson, care sunt caracteristicile sferei imaginare pe care se înscriu curbele Spee și Monson?","options":[{"id":"A","text":"Centrul sferei este la distanță egală de suprafețele ocluzale ale dinților posteriori și de centrele condiliene."},{"id":"B","text":"Centrul său se situează la nivelul glabelei."},{"id":"C","text":"A fost elaborată în 1928 de F.G. von Spee."},{"id":"D","text":"Unghiul format între planul de ocluzie și triunghiul Bonwill este de 4 inci."},{"id":"E","text":"Raza sferei este de 4 inci (10-11 cm)."}],"correct":["A","B","E"],"pages":[176],"source":"set-2"},{"id":"set2-3WGiIi0K","fingerprint":"ce72d60434b2d5b2","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Analizând înclinarea dinților în cadrul arcadelor, care dintre următoarele afirmații este corectă?","options":[{"id":"A","text":"Curbura planului de ocluzie este independentă de gradul de înclinare a dinților."},{"id":"B","text":"La maxilar, dinții anteriori sunt înclinați spre mezial, iar cei posteriori sunt orientați spre distal."},{"id":"C","text":"La mandibulă, toți dinții, atât anteriori cât și posteriori, sunt înclinați spre distal."},{"id":"D","text":"Toți dinții maxilari au o ușoară înclinare linguală."},{"id":"E","text":"Dinții posteriori mandibulari posedă o ușoară înclinare vestibulară."}],"correct":["B"],"pages":[176],"source":"set-2"},{"id":"set2-L_S4UsnF","fingerprint":"a9ad1faef2d90129","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele afirmații descriu corect tabla ocluzală?","options":[{"id":"A","text":"Suportă majoritatea forțelor de masticație."},{"id":"B","text":"Este formată din versanții externi cuspidieni."},{"id":"C","text":"Reprezintă aria dentară cuprinsă între vârfurile cuspizilor vestibulari și orali ai dinților posteriori."},{"id":"D","text":"Reprezintă aproximativ 20-30% din suprafața ocluzală totală."},{"id":"E","text":"Constituie aproximativ 50-60% din dimensiunea vestibulo-orală a dinților posteriori."}],"correct":["A","C","E"],"pages":[177],"source":"set-2"},{"id":"set2-S1rjxrCH","fingerprint":"6041a3cbea932fcc","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care este motivul principal pentru care, într-o ocluzie normală, arcada superioară o circumscrie pe cea mandibulară?","options":[{"id":"A","text":"Existența determinantului posterior, reprezentat de articulația temporo-mandibulară."},{"id":"B","text":"Dinții mandibulari sunt situați mai distal în sens sagital."},{"id":"C","text":"Spațiul mezio-distal mai mare de care dispune incisivul central inferior."},{"id":"D","text":"Cuspizii palatinali superiori sunt mai voluminoși decât cei vestibulari inferiori."},{"id":"E","text":"Lungimea medie a arcului maxilar (128 mm) este mai mare decât cea a arcului mandibular (126 mm)."}],"correct":["E"],"pages":[177],"source":"set-2"},{"id":"set2-ajGLnb7C","fingerprint":"0d448aea0ab6c18e","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt factorii determinanți care asigură stabilitatea ocluzală?","options":[{"id":"A","text":"Determinantul parodontal (integritatea ligamentelor)."},{"id":"B","text":"Determinantul scheletal (raportul maxilo-mandibular)."},{"id":"C","text":"Determinantul posterior (articular temporo-mandibular)."},{"id":"D","text":"Determinantul funcțional (neuromuscular)."},{"id":"E","text":"Determinantul anterior (dentar)."}],"correct":["C","D","E"],"pages":[177],"source":"set-2"},{"id":"set2-HuxOaJv4","fingerprint":"3535b44aabab11e3","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Ce roluri îndeplinesc cuspizii de sprijin în cadrul stabilității ocluzale?","options":[{"id":"A","text":"Nu permit migrări ale dinților."},{"id":"B","text":"Concentrează solicitările asupra dinților în afara axului lung al acestora."},{"id":"C","text":"Permit realizarea contactelor unipoziționale în ocluzie."},{"id":"D","text":"Mențin dimensiunea verticală de ocluzie."},{"id":"E","text":"Asigură contactul doar în zona frontală a arcadelor."}],"correct":["A","D"],"pages":[177],"source":"set-2"},{"id":"set2-_Trcf1H2","fingerprint":"80efae6605481117","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Conform clasificării lui Abjean și Korbendeau, din ce clasă de elemente cu rol de sprijin ocluzal fac parte marginile libere ale caninilor inferiori și cele incizale ale incisivilor inferiori?","options":[{"id":"A","text":"Clasa I"},{"id":"B","text":"Clasa I și a II-a"},{"id":"C","text":"Clasa a II-a"},{"id":"D","text":"Nu sunt considerate elemente de sprijin ocluzal."},{"id":"E","text":"Clasa a III-a"}],"correct":["C"],"pages":[177],"source":"set-2"},{"id":"set2-m_LJ4-Ne","fingerprint":"0abf4d1f7d8a3866","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"În cadrul corespondențelor generale de angrenare pentru stopurile de clasa I-a, cum se realizează contactul pentru cuspizii distali ai molarilor secunzi și ai celor de minte?","options":[{"id":"A","text":"Realizează puncte de sprijin cu creasta marginală mezială a omologului."},{"id":"B","text":"Contactează cu creasta marginală distală a dintelui situat mezial."},{"id":"C","text":"Contactează în ocluzie cap la cap cu cuspizii antagoniști."},{"id":"D","text":"Se sprijină pe fețele palatinale ale grupului frontal superior."},{"id":"E","text":"Contactează tripodic cu foseta centrală antagonistă."}],"correct":["E"],"pages":[177],"source":"set-2"},{"id":"set2-TovITQkr","fingerprint":"8f318d84de048c0d","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele reprezintă situații clinice recunoscute ale rapoartelor variate ale grupului frontal în intercuspidare?","options":[{"id":"A","text":"Contactul pe creste marginale."},{"id":"B","text":"Protruzia bimaxilară fiziologică."},{"id":"C","text":"Labiodonția (ocluzia cap la cap)."},{"id":"D","text":"Ocluzia psalidodontă."},{"id":"E","text":"Contactul tripodic în foseta centrală."}],"correct":["B","C","D"],"pages":[177],"source":"set-2"},{"id":"set2-eRmBOO9x","fingerprint":"1b38fea9fac0eb9b","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care este definiția corectă a termenului 'overbite'?","options":[{"id":"A","text":"Decalajul sagital între fețele palatinale ale frontalilor superiori și cele vestibulare ale frontalilor inferiori."},{"id":"B","text":"Coincidența intercuspidării maxime cu relația centrică."},{"id":"C","text":"Gradul de supraacoperire incisivă în plan vertical."},{"id":"D","text":"Raportul ocluzal de tip cuspid-creastă marginală."},{"id":"E","text":"Libertatea de mișcare a cuspidului de sprijin pe suprafața ocluzală antagonistă."}],"correct":["C"],"pages":[178],"source":"set-2"},{"id":"set2-TkJbeI7S","fingerprint":"a65c34706abdfe5d","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"În cadrul stopurilor de clasa a III-a, care este afirmația corectă privind contactele ocluzale ale cuspizilor palatinali superiori?","options":[{"id":"A","text":"Toți cuspizii palatinali ai premolarilor și molarilor contactează fosetele distale ale dinților omologi inferiori."},{"id":"B","text":"Toți cuspizii palatinali ai premolarilor și molarilor contactează fosetele centrale ale dinților omologi inferiori."},{"id":"C","text":"Cuspizii mezio-palatinali ai molarilor superiori contactează fosetele distale ale antagoniștilor."},{"id":"D","text":"Cuspizii palatinali ai premolarilor contactează crestele marginale ale dinților omologi inferiori."},{"id":"E","text":"Cuspizii mezio-palatinali ai molarilor superiori contactează fosetele centrale antagoniste."}],"correct":["E"],"pages":[178],"source":"set-2"},{"id":"set2-j0uLQ9Dm","fingerprint":"167f51b0918fff48","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt rolurile atribuite cuspizilor inactivi (vestibulari la maxilar și linguali la mandibulă)?","options":[{"id":"A","text":"Contactează fosetele centrale ale dinților antagoniști."},{"id":"B","text":"Realizează contacte de tip tripod în relație centrică."},{"id":"C","text":"Asigură conducerea mandibulei în mișcările de lateralitate prin versanții lor de ghidaj."},{"id":"D","text":"Contactează fiecare câte un singur versant cuspidian antagonist."},{"id":"E","text":"Anulează componentele orizontale ale forțelor ocluzale."}],"correct":["C","E"],"pages":[178],"source":"set-2"},{"id":"set2-9pXnti5u","fingerprint":"8c6052ca9c261ee2","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele caracteristici descriu schema ocluzală gnatologică (organică)?","options":[{"id":"A","text":"La nivelul dinților anteriori se evidențiază inocluzia în intercuspidare maximă."},{"id":"B","text":"Raportul ocluzal este de tip cuspid-creastă marginală."},{"id":"C","text":"Mișcarea de lateralitate se face cu protecție canină pe partea activă."},{"id":"D","text":"Contactele dento-dentare se realizează la toți dinții, atât laterali, cât și frontali."},{"id":"E","text":"Intercuspidarea maximă coincide cu relația centrică, fiind denumită 'point centric'."}],"correct":["A","C","E"],"pages":[178],"source":"set-2"},{"id":"set2-ewEv5T0k","fingerprint":"d76628a5f214f07e","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Ce presupune conceptul ocluzal „freedom in centric” promovat de școala din Florida (Pankey, Mann și Schuyler)?","options":[{"id":"A","text":"O contactare de tip tripodare, specifică ocluziei restrictive."},{"id":"B","text":"De partea nelucrătoare se produce dezocluzia dinților cuspidați în mișcarea de lateralitate."},{"id":"C","text":"Mișcarea de propulsie este asigurată de ghidajul incizal."},{"id":"D","text":"Deglutiția are loc în relație centrică, cu inocluzia dinților anteriori."},{"id":"E","text":"Existența unei zone de libertate a cuspidului de sprijin de 0,5-1 mm, anterioară poziției de contactare în relație centrică."}],"correct":["B","C","E"],"pages":[178],"source":"set-2"},{"id":"set2-DnnGYobD","fingerprint":"04b8f08550c9d420","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Conform conceptelor ocluzologice de actualitate pentru reabilitările protetice, care este abordarea recomandată?","options":[{"id":"A","text":"Implementarea sistematică a contactelor de tip tripod pentru a asigura stabilitatea maximă."},{"id":"B","text":"Crearea unei ocluzii restrictive, cu intercuspidarea maximă coincidând cu relația centrică."},{"id":"C","text":"Adoptarea unor scheme ocluzale simplificate, bazate pe conceptul 'freedom in centric'."},{"id":"D","text":"Realizarea contactelor de tip cuspid activ-fosa antagonistă, cu cuspizii inactivi în ușoară inocluzie."},{"id":"E","text":"Modelarea fosei antagoniste sub forma unei depresiuni concave."}],"correct":["C","D","E"],"pages":[178],"source":"set-2"},{"id":"set2-QHFmAvdt","fingerprint":"fafe766e572fc556","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt caracteristicile conceptului ocluzal „freedom in centric” recomandat în reabilitările protetice?","options":[{"id":"A","text":"Permite o mai bună adaptare a musculaturii masticatorii și a articulațiilor temporo-mandibulare."},{"id":"B","text":"Cuspizii inactivi sunt menținuți în ușoară inocluzie."},{"id":"C","text":"Promovează realizarea contactelor dentare punctiforme de tip cuspid activ-fosa antagonistă."},{"id":"D","text":"Vizează crearea de contacte multiple și uniforme pe întreaga arcadă dentară."},{"id":"E","text":"Fosa antagonistă este modelată concav pentru a permite traiectoriile protruzive, de laterotruzie și de mediotruzie."}],"correct":["A","B","C","E"],"pages":[179],"source":"set-2"},{"id":"set2-XfNWGZI0","fingerprint":"64c08e89571451fc","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt indicațiile ocluziei „lingualizate”, cunoscută și ca „ocluzia cu contact cuspidian palatinal”?","options":[{"id":"A","text":"Protezarea pe implanturi, fiind tiparul ocluzal de elecție."},{"id":"B","text":"Situații clinice de resorbții avansate ale crestelor edentate în protezarea mobilă."},{"id":"C","text":"Prezența unor diferențe de mărime ale arcadelor dentare."},{"id":"D","text":"Reabilitări protetice fixe în care se dorește o intercuspidare maximă de tip cuspid-ambrazură."},{"id":"E","text":"Tratamentul edentației parțiale terminale prin proteze mobilizabile cu atașamente."}],"correct":["A","B","C","E"],"pages":[179],"source":"set-2"},{"id":"set2-4hep4bXQ","fingerprint":"cdd2d018c72bf18c","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Conform școlii gnatologice a lui Korber, ce reprezintă factorul „forță” în caracterizarea ocluziei funcționale?","options":[{"id":"A","text":"Lipsa edentațiilor."},{"id":"B","text":"Contacte dentare multipoziționale."},{"id":"C","text":"Alunecarea dento-dentară fără obstacole."},{"id":"D","text":"Contacte dentare simultane."},{"id":"E","text":"Repartizarea uniformă a solicitărilor ocluzale."}],"correct":["E"],"pages":[179],"source":"set-2"},{"id":"set2-j5Ekdhw6","fingerprint":"f592bc0387b70180","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care este semnificația clinică a prelungirii timpului de ocluzie (OT) și a timpului de dezocluzie (DT)?","options":[{"id":"A","text":"Reprezintă un indicator al unei ocluzii funcționale stabile."},{"id":"B","text":"Facilitează adaptarea musculaturii masticatorii la noile restaurări protetice."},{"id":"C","text":"Constituie un factor predispozant pentru instalarea unei disfuncții craniomandibulare."},{"id":"D","text":"Se corelează cu realizarea unei uzuri fiziologice a dinților."},{"id":"E","text":"Nu are relevanță clinică dacă stopurile ocluzale sunt stabile."}],"correct":["C"],"pages":[179],"source":"set-2"},{"id":"set2-_Fxsjqre","fingerprint":"d99156961eeedf25","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce valoare fiziologică trebuie să aibă timpul de ocluzie (OT), reprezentând intervalul de la primul contact dentar până la intercuspidarea maximă?","options":[{"id":"A","text":"Peste 0.5 secunde."},{"id":"B","text":"Între 0.4 și 0.6 secunde."},{"id":"C","text":"Sub 0.2 secunde."},{"id":"D","text":"Sub 0.4 secunde."},{"id":"E","text":"Nu există o valoare standardizată."}],"correct":["C"],"pages":[179],"source":"set-2"},{"id":"set2-o6WcakWo","fingerprint":"63676e018e37ac4a","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt funcțiile stopurilor ocluzale stabile și simultane, conform școlii gnatologice din Florida?","options":[{"id":"A","text":"Permit alunecarea mandibulei fără impacte."},{"id":"B","text":"Asigură armonia între ghidajul anterior și panta tuberculilor articulari."},{"id":"C","text":"Dirijează solicitările ocluzale în axul lung al dinților."},{"id":"D","text":"Previn migrările dentare."},{"id":"E","text":"Reduc constrângerile la care este supus fiecare dinte."}],"correct":["A","C","D","E"],"pages":[179],"source":"set-2"},{"id":"set2-mz7NAG4N","fingerprint":"724fa4ccb02cfbc3","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce consecință poate avea un ghidaj anterior abrupt în contextul unei tendințe exagerate de mișcări orizontale ale mandibulei?","options":[{"id":"A","text":"O mai bună adaptare a musculaturii masticatorii."},{"id":"B","text":"Realizarea unei uzuri fiziologice a dinților frontali."},{"id":"C","text":"Dirijarea solicitărilor ocluzale exclusiv în axul lung al dinților."},{"id":"D","text":"Dezocluzia imediată și uniformă a dinților laterali."},{"id":"E","text":"Apariția de interferențe ocluzale generatoare de disfuncții."}],"correct":["E"],"pages":[179],"source":"set-2"},{"id":"set2-aiBAIv8H","fingerprint":"13ae66d771dd7a69","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Conform principiilor școlii gnatologice din Florida, ce caracterizează o mișcare de propulsie normală cu contactare dento-dentară?","options":[{"id":"A","text":"Implică obligatoriu contacte pe dinții cuspidați până la finalul mișcării."},{"id":"B","text":"Se desfășoară printr-o mișcare uniformă, fără devierea mandibulei."},{"id":"C","text":"Dinții laterali trebuie să fie în inocluzie în poziția cap la cap a dinților frontali."},{"id":"D","text":"Determinarea apariției de interferențe pe partea de mediotruzie."},{"id":"E","text":"Este ghidată exclusiv de contactele dentare posterioare."}],"correct":["B","C"],"pages":[179],"source":"set-2"},{"id":"set2-Hu_WG-Vm","fingerprint":"2fa51f326c760d50","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt caracteristicile unei mișcări de propulsie cu contactare dento-dentară, în condiții normale?","options":[{"id":"A","text":"În poziția propulsată, condilii sunt susținuți ferm în cavitățile glenoide, asigurând stabilitate."},{"id":"B","text":"Poziția cap la cap trebuie să fie susținută de cel puțin două perechi de dinți frontali antagoniști."},{"id":"C","text":"Contactele care determină devieri în zona frontală se numesc interferențe pasive."},{"id":"D","text":"Mișcarea se desfășoară uniform, fără devierea mandibulei."},{"id":"E","text":"Dinții cuspidați au un rol funcțional esențial în incizia alimentelor în timpul propulsiei."}],"correct":["B","D"],"pages":[180],"source":"set-2"},{"id":"set2-OtX5l7N8","fingerprint":"df2eedbb5b14edbf","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Cum este denumit un contact dentar care determină devierea mandibulei în cursul propulsiei și este localizat în zonele laterale sau distale ale arcadelor?","options":[{"id":"A","text":"Ghidaj de grup"},{"id":"B","text":"Interferență activă"},{"id":"C","text":"Contact prematur nelucrător"},{"id":"D","text":"Interferență pasivă"},{"id":"E","text":"Contact prematur lucrător"}],"correct":["D"],"pages":[180],"source":"set-2"},{"id":"set2-Ywfr1ghw","fingerprint":"049ff22175fef236","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce definește un contact prematur lucrător în contextul mișcării de propulsie?","options":[{"id":"A","text":"Situația în care poziția cap la cap este susținută de un singur dinte."},{"id":"B","text":"Poziția cap la cap susținută de două perechi de dinți antagoniști."},{"id":"C","text":"Un contact în zona frontală ce provoacă devierea mandibulei."},{"id":"D","text":"Un contact pe partea de balans în timpul mișcării de lateralitate."},{"id":"E","text":"Un contact în zona laterală care apare în poziția cap la cap a frontalilor."}],"correct":["A"],"pages":[180],"source":"set-2"},{"id":"set2-ilaNXKI2","fingerprint":"04630ecad53fbdc9","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt motivele pentru care dezocluzia dinților cuspidați în timpul mișcării de propulsie este esențială?","options":[{"id":"A","text":"În propulsie, forțele pe dinții cuspidați sunt orientate paraaxial."},{"id":"B","text":"Dinții frontali, având rădăcini lungi și suport osos adaptat, sunt specializați pentru secționarea alimentelor."},{"id":"C","text":"Contactele de partea inactivă în propulsie generează bruxism."},{"id":"D","text":"Dinții cuspidați nu au rol funcțional în procesul de incizie a alimentelor."},{"id":"E","text":"Contactele laterale în propulsie ar deveni nocive deoarece condilii nu sunt susținuți ferm în cavitățile glenoide."}],"correct":["B","D","E"],"pages":[180],"source":"set-2"},{"id":"set2-w4FBoR5D","fingerprint":"19d7cdefbab11b71","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt argumentele care susțin importanța dezocluziei dinților cuspidați de pe partea inactivă (de balans) în mișcarea de lateralitate?","options":[{"id":"A","text":"Dinții de pe partea inactivă sunt esențiali pentru triturarea alimentelor."},{"id":"B","text":"Condilul orbitant (nelucrător) nu mai beneficiază de sprijin în articulație."},{"id":"C","text":"Contactele de pe partea inactivă sunt ineficiente din punct de vedere funcțional."},{"id":"D","text":"Forțele generate de contactele pe partea inactivă sunt orientate paraaxial."},{"id":"E","text":"Prezența contactelor pe partea inactivă poate genera bruxism."}],"correct":["B","C","D","E"],"pages":[180],"source":"set-2"},{"id":"set2-wsELPvTW","fingerprint":"c1bd4b07a092e9e0","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce tip de ghidaj în mișcarea de lateralitate este realizat simultan de pantele palatinale ale caninilor (și posibil ale incisivilor) și de pantele de ghidaj laterotrusive (pantele orale ale cuspizilor vestibulari maxilari)?","options":[{"id":"A","text":"Conducere canină"},{"id":"B","text":"Ghidaj de grup"},{"id":"C","text":"Conceptul biodinamic"},{"id":"D","text":"Ghidaj secvențial cu predominanță canină"},{"id":"E","text":"Ghidaj antero-lateral"}],"correct":["B"],"pages":[180],"source":"set-2"},{"id":"set2-4JhJ0ezQ","fingerprint":"be1ebfc0682c994c","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce particularitate prezintă conceptul ghidajului secvențial cu predominanță canină, promovat de Slavicek?","options":[{"id":"A","text":"Traiectoria ghidajului fiecărui dinte realizează cu planul de la Frankfurt un unghi cu valoare descrescândă de la incisivi la canini, premolari și molari."},{"id":"B","text":"Ghidarea în lateralitate este realizată exclusiv de canini, indiferent de pantele palatinale."},{"id":"C","text":"Traiectoria ghidajului fiecărui dinte realizează cu planul de la Frankfurt un unghi cu valoare crescătoare de la incisivi la molari."},{"id":"D","text":"Promovează ideea că nu există un singur tipar de morfologie ocluzală valabil pentru toți indivizii."},{"id":"E","text":"Mișcările excentrice ale mandibulei pornesc și revin obligatoriu în poziția centrică."}],"correct":["A"],"pages":[180],"source":"set-2"},{"id":"set2-xfecsT5l","fingerprint":"88e5237045b909a2","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele afirmații descriu corect conceptul biodinamic al lui Heinz Polz (conceptul „busolei ocluzale”)?","options":[{"id":"A","text":"Ghidajul este asigurat exclusiv prin conducere canină datorită rădăcinilor puternice."},{"id":"B","text":"Mișcările excentrice ale mandibulei, cu contactare dento-dentară, pornesc din poziția centrică și revin în aceasta."},{"id":"C","text":"La nivelul fiecărui dinte, cuspizii de sprijin efectuează traiectorii individuale de protruzie, laterotruzie și mediotruzie."},{"id":"D","text":"Valoarea unghiului traiectoriei de ghidaj față de planul Frankfurt este descrescătoare de la incisivi la molari."},{"id":"E","text":"Există un singur tipar ideal de morfologie ocluzală care trebuie replicat pentru toți indivizii."}],"correct":["B","C"],"pages":[180],"source":"set-2"},{"id":"set2-5TzpJDsE","fingerprint":"1adbda95e37fdb31","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care este principiul fundamental al conceptului biodinamic, cunoscut și sub denumirea de „busola ocluzală”?","options":[{"id":"A","text":"Traiectoriile cuspidiene sunt independente de tehnicile de adiție de ceară."},{"id":"B","text":"Nu există un model unic de morfologie ocluzală valabil pentru toți indivizii."},{"id":"C","text":"Mișcările excentrice ale mandibulei se finalizează în afara poziției centrice în timpul masticației."},{"id":"D","text":"La nivelul fiecărui dinte, cuspizii de sprijin efectuează traiectorii individuale de protruzie, laterotruzie și mediotruzie."},{"id":"E","text":"Toți indivizii prezintă un tipar morfologic ocluzal universal."}],"correct":["B","D"],"pages":[181],"source":"set-2"},{"id":"set2-5OMk8_jj","fingerprint":"613b72548cf340ce","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele afirmații sunt cauze posibile ale interferențelor la nivelul cuspizilor de pe partea activă în mișcarea de lateralitate?","options":[{"id":"A","text":"Modificări ale curbei Spee cauzate de edentații sau migrări dentare."},{"id":"B","text":"Anomalii dento-maxilare."},{"id":"C","text":"Tratamente ortodontice corect executate."},{"id":"D","text":"O morfologie ocluzală modelată incorect."},{"id":"E","text":"Un ghidaj cu înclinație mare realizat la lucrările protetice."}],"correct":["A","B","D"],"pages":[181],"source":"set-2"},{"id":"set2-j5NRLlTq","fingerprint":"924910f9f223c429","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Ce criterii suplimentare, pe lângă cele legate de ghidaj, sunt caracteristice unei ocluzii funcționale?","options":[{"id":"A","text":"Masticația trebuie să fie unilaterală și monodirecțională."},{"id":"B","text":"Abraziunea dentară să se producă uniform."},{"id":"C","text":"Existența unui echilibru al grupelor musculare linguo-oro-faciale."},{"id":"D","text":"Prezența unei patologii articulare temporo-mandibulare controlate."},{"id":"E","text":"Dimensiunea verticală de ocluzie să fie optimă."}],"correct":["B","C","E"],"pages":[181],"source":"set-2"},{"id":"set2-UYKmCPxJ","fingerprint":"d15f0814f336b90a","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce tip de articulație este articulația temporo-mandibulară umană și ce mișcări permite?","options":[{"id":"A","text":"Este de tip fibros și permite mișcări limitate de alunecare."},{"id":"B","text":"Este de tip ginglimo-artroidal și permite concomitent mișcări de rotație și de translație ale condililor."},{"id":"C","text":"Este de tip ginglimo-artroidal și permite doar mișcări de rotație."},{"id":"D","text":"Este de tip sinovial și permite exclusiv mișcări de translație."},{"id":"E","text":"Este de tip ginglimo-artroidal și permite doar mișcări de translație."}],"correct":["B"],"pages":[181],"source":"set-2"},{"id":"set2-VvnSe9xC","fingerprint":"1fd7d6c53297fe63","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care este o caracteristică distinctivă a țesutului care acoperă suprafețele articulare ale articulației temporo-mandibulare?","options":[{"id":"A","text":"Este un țesut elastic ce permite deformări mari."},{"id":"B","text":"Este un țesut fibros avascular."},{"id":"C","text":"Este un țesut conjunctiv dens, bogat vascularizat."},{"id":"D","text":"Este un țesut fibros vascular, în contrast cu alte articulații care au cartilaj hialin."},{"id":"E","text":"Este un cartilaj hialin, similar cu cel din majoritatea articulațiilor."}],"correct":["B"],"pages":[181],"source":"set-2"},{"id":"set2-aFZiOteQ","fingerprint":"556eef73e94065e9","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Ce caracteristici dimensionale și de orientare descriu condilul mandibular?","options":[{"id":"A","text":"Axele lungi condiliene formează un unghi deschis posterior, de aproximativ 90 de grade."},{"id":"B","text":"Prelungirile axelor condiliene se intersectează de obicei posterior de foramen magnum."},{"id":"C","text":"Are o dimensiune antero-posterioară de 8-10 mm."},{"id":"D","text":"Transformă suprafețele articulare în unele congruente."},{"id":"E","text":"Are o formă elipsoidală, cu dimensiunea transversală de 8-20 mm."}],"correct":["C","E"],"pages":[181],"source":"set-2"},{"id":"set2-qsJ_BZBs","fingerprint":"bcd4c076bf9e349c","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt funcțiile meniscului articular în cadrul articulației temporo-mandibulare?","options":[{"id":"A","text":"Separă cavitatea articulară în două compartimente: unul superior temporo-meniscal și unul inferior menisco-condilian."},{"id":"B","text":"De detectare a presiunilor prin fibrele nervoase din zona centrală."},{"id":"C","text":"Amortizează presiunile exercitate asupra articulațiilor."},{"id":"D","text":"Rol de tampon"},{"id":"E","text":"Prin caracterul său ginglimo-artroidal, facilitează lateralitatea mandibulei."}],"correct":["A","C","D"],"pages":[181],"source":"set-2"},{"id":"set2-6zeLziWS","fingerprint":"5285f0761b474cb7","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Ce structură se fixează posterior de meniscul articular și care este compoziția sa?","options":[{"id":"A","text":"Capsula articulară, formată din țesut conjunctiv avascular."},{"id":"B","text":"Zona bilaminară, formată dintr-un strat superior elastic și unul inferior colagenic, neelastic."},{"id":"C","text":"Zona bilaminară, compusă din două straturi colagenice cu proprietăți elastice identice."},{"id":"D","text":"Zona bilaminară, alcătuită din țesut retromeniscal conjunctiv vascularizat."},{"id":"E","text":"Fascicolul superior al mușchiului pterigoidian lateral, format din fibre musculare striate."}],"correct":["B","D"],"pages":[181],"source":"set-2"},{"id":"set2-3HX9Re-s","fingerprint":"d230ec3e5cae41bf","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt caracteristicile zonei bilaminare, cunoscută și sub denumirea de atașament posterior meniscal?","options":[{"id":"A","text":"Leagă meniscul de polii condilieni medial și lateral."},{"id":"B","text":"Contribuie la sprijinul vascular hidrodinamic pentru poziționarea corectă condilo-meniscală."},{"id":"C","text":"Este alcătuită din țesut retromeniscal conjunctiv vascularizat."},{"id":"D","text":"Conține un strat superior colagenic și un strat inferior elastic."},{"id":"E","text":"Permite poziționarea mandibulei în ocluzie habituală fără influența factorului muscular."}],"correct":["B","C","E"],"pages":[182],"source":"set-2"},{"id":"set2-7D4kiGkY","fingerprint":"0f35ee70d68eb010","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care este rolul principal al ligamentelor articulare temporomandibulare?","options":[{"id":"A","text":"Să asigure mișcările reflexe ale mandibulei."},{"id":"B","text":"Să ofere sprijin vascular pentru poziționarea condilo-meniscală."},{"id":"C","text":"Să inițieze mișcările de propulsie și retropulsie ale mandibulei."},{"id":"D","text":"Să stabilizeze articulația în timpul mișcărilor dinamice excentrice."},{"id":"E","text":"Să limiteze mișcările extreme ale articulației și să întărească capsula."}],"correct":["E"],"pages":[182],"source":"set-2"},{"id":"set2-Bh1q5cyQ","fingerprint":"76a940ed24ca02c7","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce tip de mișcări mandibulare sunt determinate de stimularea la nivel bulbo-protuberențial?","options":[{"id":"A","text":"Mișcările de propulsie și retropulsie."},{"id":"B","text":"Mișcările de închidere a gurii."},{"id":"C","text":"Mișcările voluntare."},{"id":"D","text":"Mișcările reflexe."},{"id":"E","text":"Mișcările automatizate."}],"correct":["D"],"pages":[182],"source":"set-2"},{"id":"set2-6UIzE1NH","fingerprint":"03c8c15f1794ecd6","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care dintre următoarele grupe musculare sunt responsabile în principal de menținerea poziției de postură a mandibulei?","options":[{"id":"A","text":"Mușchiul milohioidian și pântecul anterior al digastricului."},{"id":"B","text":"Mușchiul stilohioidian și pântecul posterior al digastricului."},{"id":"C","text":"Mușchiul pterigoidian medial și pterigoidian lateral."},{"id":"D","text":"Porțiunea profundă a maseterului și fascicolul superior al pterigoidianului lateral."},{"id":"E","text":"Mușchiul temporal și mușchiul maseter."}],"correct":["B"],"pages":[182],"source":"set-2"},{"id":"set2-FUjqQ0te","fingerprint":"56ab11c17c18080c","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt afirmațiile corecte referitoare la mușchii sistemului cranio-mandibular (porțiunea profundă a maseterului, fascicolul superior al pterigoidianului lateral și fascicolul anterior al temporalului)?","options":[{"id":"A","text":"Sunt activi în poziția de postură și la închiderea gurii."},{"id":"B","text":"Au rolul de mușchi posturali, stabilizatori ai articulației temporomandibulare."},{"id":"C","text":"Vectorii de forță ai acestor mușchi au o orientare generală postero-inferioară."},{"id":"D","text":"Din acest grup fac parte mușchiul milohioidian și mușchiul geniohioidian."},{"id":"E","text":"Acești mușchi sunt foarte activi în timpul mișcărilor dinamice excentrice ale mandibulei."}],"correct":["A","B"],"pages":[182],"source":"set-2"},{"id":"set2-WNLUoU3i","fingerprint":"197f168c4f13894a","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Ce elemente ale morfologiei și cinematicii articulare temporomandibulare sunt definitorii pentru programarea articulatoarelor în reabilitările orale?","options":[{"id":"A","text":"Gradul de vascularizație al zonei bilaminare."},{"id":"B","text":"Configurația peretelui medial al cavității glenoide."},{"id":"C","text":"Înclinația pantei tuberculului articular."},{"id":"D","text":"Gradul de laxitate al ligamentelor articulare."},{"id":"E","text":"Tipul de stimulare nervoasă (corticală, bulbară, mezencefalică)."}],"correct":["B","C","D"],"pages":[182],"source":"set-2"},{"id":"set2-UdLg11j7","fingerprint":"2325a0c5e9b5e7e0","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce definește poziția fiziologică de postură a mandibulei?","options":[{"id":"A","text":"O relație statică în care între arcadele dentare există un spațiu liber interdentar de 1,2-4 mm."},{"id":"B","text":"O poziție caracterizată prin numărul maxim de contacte dento-dentare punctiforme."},{"id":"C","text":"O poziție în care dimensiunea verticală de ocluzie (DVO) este direct proporțională cu inocluzia fiziologică."},{"id":"D","text":"Poziția în care condilii mandibulari se găsesc într-o situare stabilă ortopedic, antero-superioară."},{"id":"E","text":"O relație constantă și invariabilă, independentă de factorii loco-regionali sau generali."}],"correct":["A"],"pages":[183],"source":"set-2"},{"id":"set2-uiB8HA_E","fingerprint":"f6c93fb85ef5b341","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care este descrierea corectă a poziționării condililor mandibulari în relația centrică (RC)?","options":[{"id":"A","text":"Sunt situați pe pantele posterioare ale eminențelor articulare, într-o poziție stabilă ortopedic."},{"id":"B","text":"Este o poziție dependentă exclusiv de contactele dento-dentare."},{"id":"C","text":"Sunt centrați de fascicolul inferior al mușchiului pterigoidian lateral."},{"id":"D","text":"Se află într-o poziție limită inferioară, din care se execută mișcări de propulsie."},{"id":"E","text":"Se găsesc într-o poziție postero-inferioară în fosele articulare, fără interpunerea meniscului."}],"correct":["A"],"pages":[183],"source":"set-2"},{"id":"set2-Eub-iayp","fingerprint":"a028ec8a82120e6a","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce avantaje prezintă poziția de intercuspidare maximă (IM)?","options":[{"id":"A","text":"Permite contracția simetrică, egală și maximă a mușchilor ridicători ai mandibulei."},{"id":"B","text":"Coincide întotdeauna cu poziția de relație centrică a mandibulei."},{"id":"C","text":"Este considerată o poziție diagnostică reproductibilă în toate cazurile clinice."},{"id":"D","text":"Asigură crearea unui spațiu liber interdentar de 1,2-4 mm."},{"id":"E","text":"Forțele ocluzale sunt orientate orizontal pentru a maximiza eficiența masticatorie."}],"correct":["A"],"pages":[183],"source":"set-2"},{"id":"set2-cuc1Q1Oy","fingerprint":"f9f477e7e6612f41","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele afirmații sunt corecte cu privire la relația centrică (RC)?","options":[{"id":"A","text":"Vectorii de forțe ai mușchilor specializați au o direcție antero-superioară, centrând condilii."},{"id":"B","text":"Este definită de numărul maxim de contacte dento-dentare, fiind dependentă de ocluzie."},{"id":"C","text":"Este o poziție protetică reproductibilă, fiind o poziție superioară limită a condililor."},{"id":"D","text":"Din această poziție se pot executa mișcări balama terminale în jurul axei balama terminale bicondiliene."},{"id":"E","text":"Este o poziție protetică nereproductibilă, fiind o poziție superioară limită a condililor"}],"correct":["A","C","D"],"pages":[183],"source":"set-2"},{"id":"set2--Lmb2P8k","fingerprint":"42d6e95c089aa173","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"În ce procent din cazuri coincide intercuspidarea maximă (IM) cu poziția de relație centrică (RC), formând așa-numitul 'point centric'?","options":[{"id":"A","text":"12%"},{"id":"B","text":"25%"},{"id":"C","text":"50%"},{"id":"D","text":"Nu există cazuri de coincidență între IM și RC."},{"id":"E","text":"100%"}],"correct":["A"],"pages":[183],"source":"set-2"},{"id":"set2-Nr_WOhQF","fingerprint":"3d7496ef9e0c98a7","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt caracteristicile intercuspidării maxime atunci când aceasta coincide cu relația centrică?","options":[{"id":"A","text":"Prezența unui spațiu liber interdentar de 4 mm."},{"id":"B","text":"Prezența unităților masticatorii."},{"id":"C","text":"Contracția mușchilor ridicători este asimetrică și submaximală."},{"id":"D","text":"Condilii mandibulari se află în cea mai posterioară poziție posibilă."},{"id":"E","text":"Liniile mediene ale arcadelor sunt situate în același plan."}],"correct":["B","E"],"pages":[183],"source":"set-2"},{"id":"set2-x1MNQu9m","fingerprint":"5c3c28d1651d8b27","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"În ce situații clinice este frecvent întâlnită modificarea raportului dintre inocluzia fiziologică și dimensiunea verticală de ocluzie?","options":[{"id":"A","text":"Abraziuni patologice."},{"id":"B","text":"Edentații parțiale extinse și subtotale."},{"id":"C","text":"Cazuri cu ocluzie ideală și arcade integre."},{"id":"D","text":"Anomalii dento-maxilare de tipul ocluziilor adânci."},{"id":"E","text":"Reconstituiri protetice realizate în supraocluzie."}],"correct":["A","B","D"],"pages":[183],"source":"set-2"},{"id":"set2-HwBfXgKP","fingerprint":"867b37e2d328f89b","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt funcțiile îndeplinite de poziția de intercuspidare maximă?","options":[{"id":"A","text":"Orientează forțele ocluzale în axul lung al dinților."},{"id":"B","text":"Este considerată o poziție diagnostică esențială în analiza ocluzală."},{"id":"C","text":"Anulează și compensează forțele orizontale."},{"id":"D","text":"Permite contracția asimetrică și inegală a mușchilor ridicători ai mandibulei."},{"id":"E","text":"Asigură stabilitatea mandibulei față de maxilar."}],"correct":["A","C","E"],"pages":[184],"source":"set-2"},{"id":"set2-3n4ziXh7","fingerprint":"804b59ebced7e380","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"În ce procentaj de cazuri coincide intercuspidarea maximă cu poziția de relație centrică a mandibulei, situație cunoscută sub denumirea de \"point centric\"?","options":[{"id":"A","text":"12%"},{"id":"B","text":"50%"},{"id":"C","text":"0%"},{"id":"D","text":"25%"},{"id":"E","text":"75%"}],"correct":["A"],"pages":[184],"source":"set-2"},{"id":"set2-H-jVtkwT","fingerprint":"522cca285130d7e5","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele afirmații descriu corect parametrii ocluzologici ai intercuspidării maxime în relație centrică?","options":[{"id":"A","text":"Cuspizii vestibulari inferiori circumscriu cuspizii vestibulari superiori."},{"id":"B","text":"Arcada inferioară are o poziționare distalizată."},{"id":"C","text":"Cuspizii linguali sunt situați oral în raport cu cei palatinali."},{"id":"D","text":"Fețele distale ale ultimilor molari se află în plane diferite."},{"id":"E","text":"Liniile mediene ale arcadelor sunt situate în același plan."}],"correct":["C","E"],"pages":[184],"source":"set-2"},{"id":"set2-177HSGH0","fingerprint":"02b428948c26f54c","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce definește conceptul ocluzologic de \"long centric\"?","options":[{"id":"A","text":"O alunecare sagitală a mandibulei, cu contact dentar, din relație centrică în intercuspidare maximă, pe o distanță de 1,25-1,5 mm."},{"id":"B","text":"Coincidența perfectă între intercuspidarea maximă și poziția de relație centrică a mandibulei."},{"id":"C","text":"O contactare dento-dentară impusă, care se produce în afara relației centrice."},{"id":"D","text":"O libertate de deplasare a cuspidului cu o înălțime de 0,2-1,75 mm, cunoscută ca „triunghi de toleranță ocluzală”."},{"id":"E","text":"O deplasare laterală a cuspidului de sprijin în foseta antagonistă, cu o bază de 2 mm."}],"correct":["A"],"pages":[184],"source":"set-2"},{"id":"set2-7mTHecYZ","fingerprint":"d6696cc0c0f9de84","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce dimensiuni caracterizează \"triunghiul de toleranță ocluzală\", care descrie libertatea de deplasare a cuspidului de sprijin?","options":[{"id":"A","text":"O bază de 2 mm orientată anterior și o înălțime de 1,25-1,5 mm."},{"id":"B","text":"O bază de 2 mm și o înălțime de 2 mm."},{"id":"C","text":"O bază de 2 mm orientată posterior și o înălțime de 0,2-1,75 mm."},{"id":"D","text":"O bază de 0,2-1,75 mm și o înălțime de 2 mm."},{"id":"E","text":"O bază de 1,25-1,5 mm și o înălțime de 2 mm."}],"correct":["C"],"pages":[184],"source":"set-2"},{"id":"set2-MUdQWNYw","fingerprint":"39eedf09c1c0b310","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Conform clasificării gnatologice a relațiilor ocluzale statice, ce caracterizează relațiile de Tip II?","options":[{"id":"A","text":"Relația ocluzală este într-o fază de alterare continuă din cauza instabilității ATM."},{"id":"B","text":"Condilii trebuie să se deplaseze de la o relație centrică verificabilă pentru a realiza intercuspidarea maximă."},{"id":"C","text":"Intercuspidarea maximă este în armonie cu o „postură centrică adaptată”."},{"id":"D","text":"Relația centrică nu poate fi verificată, iar articulațiile nu pot accepta solicitări fără a cauza disconfort."},{"id":"E","text":"Intercuspidarea maximă se realizează în armonie cu o relație centrică verificabilă."}],"correct":["B"],"pages":[184],"source":"set-2"},{"id":"set2-KaEW8ufi","fingerprint":"46559f3abd5ab32f","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce tip de relație ocluzală este considerată tranzitorie și tratabilă, fiind caracterizată prin incapacitatea de a verifica relația centrică și prin disconfort la solicitări articulare?","options":[{"id":"A","text":"Tip IV"},{"id":"B","text":"Tip II"},{"id":"C","text":"Tip I A"},{"id":"D","text":"Tip III"},{"id":"E","text":"Tip I"}],"correct":["D"],"pages":[184],"source":"set-2"},{"id":"set2-dvx9brUF","fingerprint":"fe280b1261c33bb5","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ocluzia deschisă frontală progresivă și retruzia mandibulară progresivă sunt manifestări clinice specifice cărui tip de relație ocluzală, conform clasificării gnatologice?","options":[{"id":"A","text":"Tip II"},{"id":"B","text":"Tip II A"},{"id":"C","text":"Tip IV"},{"id":"D","text":"Tip III"},{"id":"E","text":"Tip I A"}],"correct":["C"],"pages":[184],"source":"set-2"},{"id":"set2-esij-R3V","fingerprint":"40065cc6c631427b","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care sunt implicațiile clinice și prognosticul pentru relațiile ocluzale de Tip II și Tip II A?","options":[{"id":"A","text":"Alterare continuă și progresivă a ocluziei, necesitând intervenții complexe."},{"id":"B","text":"O armonie perfectă care nu necesită nicio intervenție terapeutică."},{"id":"C","text":"Lipsa disconfortului, prognostic excelent și reversibilitate la Tip I sau I A prin corectarea ocluziei."},{"id":"D","text":"Prezența constantă a disconfortului în ATM, cu un prognostic rezervat."},{"id":"E","text":"Sunt considerate stări tranzitorii, dar netratabile."}],"correct":["C"],"pages":[184],"source":"set-2"},{"id":"set2-1S6S1K8I","fingerprint":"ab66e24f52f91e65","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"În care dintre următoarele tipuri de disfuncții ale articulației temporo-mandibulare (ATM) sunt contraindicate procedurile precum chirurgia ATM, artroscopia sau injecțiile intraarticulare?","options":[{"id":"A","text":"Tip I și subtipurile acestuia"},{"id":"B","text":"Tulburările neuromusculare asociate"},{"id":"C","text":"Tip II și subtipurile acestuia"},{"id":"D","text":"Tip IV"},{"id":"E","text":"Tip III"}],"correct":["A","C"],"pages":[185],"source":"set-2"},{"id":"set2-KmXAU94O","fingerprint":"a96fe9f8aa9d34fa","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care este obiectivul terapeutic principal în managementul disfuncției ATM de tip III, înainte de finalizarea tratamentului ocluzal?","options":[{"id":"A","text":"Transformarea acesteia în tipul I sau I A"},{"id":"B","text":"Amendarea durerii musculare prin eliminarea interferențelor ocluzale"},{"id":"C","text":"Eliminarea necesității utilizării agenților medicamentoși"},{"id":"D","text":"Obținerea unei poziționări stabile a condililor"},{"id":"E","text":"Contraindicarea definitivă a spălăturilor intraarticulare"}],"correct":["A"],"pages":[185],"source":"set-2"},{"id":"set2-4NbFGfz1","fingerprint":"0a408681171507a9","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Prin ce metodă specifică poate fi identificată poziția miocentrică a mandibulei?","options":[{"id":"A","text":"Prin observarea directă a contactelor dentare în poziția de repaus a mandibulei"},{"id":"B","text":"Prin analiza cinematică a mișcărilor funcționale în timpul fonației"},{"id":"C","text":"Prin stimularea electrică bilaterală a musculaturii ridicătoare cu ajutorul unui miomonitor"},{"id":"D","text":"Prin înregistrarea poziției unde intercuspidarea maximă coincide cu relația centrică"},{"id":"E","text":"Prin ghidaj manual al mandibulei în poziția cea mai apropiată de intercuspidarea maximă"}],"correct":["C"],"pages":[185],"source":"set-2"},{"id":"set2-fqJJNnJj","fingerprint":"b58f4977e9f4969a","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele reprezintă criterii de clasificare a mișcărilor mandibulei?","options":[{"id":"A","text":"Amplitudinea mișcărilor"},{"id":"B","text":"Direcția traiectoriei deplasărilor mandibulei"},{"id":"C","text":"Tipul de articulație implicat"},{"id":"D","text":"Viteza de execuție a mișcării"},{"id":"E","text":"Contactarea dento-dentară"}],"correct":["A","B","E"],"pages":[185],"source":"set-2"},{"id":"set2-CPKG3-_k","fingerprint":"7d799381254736a4","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care este relația dintre mișcările funcționale și mișcările limită (extreme) ale mandibulei?","options":[{"id":"A","text":"Aria mișcărilor limită este o subcategorie a ariei mișcărilor funcționale"},{"id":"B","text":"Mișcările funcționale au o amplitudine mult mai redusă și se încadrează în aria mișcărilor limită"},{"id":"C","text":"Ligamentele ATM permit exclusiv realizarea mișcărilor limită"},{"id":"D","text":"Mișcările limită sunt reduse la mișcări funcționale prin acțiunea musculaturii mobilizatoare și a ligamentelor ATM"},{"id":"E","text":"Mișcările funcționale și cele limită au aceeași amplitudine în timpul masticației"}],"correct":["D"],"pages":[185],"source":"set-2"},{"id":"set2-vyRXDukD","fingerprint":"9469f440b3f58054","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce formă geometrică caracteristică are imaginea spațială tridimensională a ariei de mișcare a punctului interincisiv inferior?","options":[{"id":"A","text":"Bicuspidoidă"},{"id":"B","text":"Sferică"},{"id":"C","text":"Piramidală"},{"id":"D","text":"Cilindrică"},{"id":"E","text":"Elipsoidală"}],"correct":["A"],"pages":[185],"source":"set-2"},{"id":"set2-3BSN1WEw","fingerprint":"b8d8dea9bbb3ce1b","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Conform analizei cinematicii mandibulare în plan sagital, care sunt valorile distanțelor parcurse de punctul interincisiv inferior?","options":[{"id":"A","text":"Distanța parcursă de la poziția de relație centrică la propulsia maximă este de 10 mm."},{"id":"B","text":"Punctul interincisiv inferior parcurge 10 mm de la poziția de relație centrică la cea de cap la cap."},{"id":"C","text":"Punctul interincisiv inferior parcurge 4 mm de la poziția de relație centrică la cea de cap la cap."},{"id":"D","text":"Distanța parcursă de la poziția de relație centrică la propulsia maximă este de 4 mm."},{"id":"E","text":"Distanța totală parcursă în plan sagital este de 14 mm, de la poziția de cap la cap la propulsie maximă."}],"correct":["A","C"],"pages":[185],"source":"set-2"},{"id":"set2-1k11s9dO","fingerprint":"a119214af5291894","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care este descrierea traiectoriei parcurse de condilii mandibulari de-a lungul eminenței articulare, de la poziția de relație centrică (RC) la cea de propulsie maximă (PM)?","options":[{"id":"A","text":"O traiectorie de 10-15 mm, strict orizontală, corespunzătoare situației de long centric."},{"id":"B","text":"O traiectorie de 10-15 mm sub forma unui semicerc, parte a unui cerc imaginar cu raza de 20 mm."},{"id":"C","text":"O traiectorie de 5-10 mm sub forma unui semicerc, parte a unui cerc imaginar cu raza de 20 mm."},{"id":"D","text":"O traiectorie de 20 mm sub forma unui cerc complet, cu raza de 10-15 mm."},{"id":"E","text":"Un decalaj strict orizontal între poziția de RC și IM, de 0.5 mm."}],"correct":["B"],"pages":[186],"source":"set-2"},{"id":"set2-jtSnQyhZ","fingerprint":"cd0fb001c22e1383","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt afirmațiile corecte referitoare la analiza cinematicii mandibulare în plan orizontal?","options":[{"id":"A","text":"Aria mișcărilor funcționale se situează la distanță de poziția de intercuspidare maximă."},{"id":"B","text":"Reprezentarea schematică a deplasării punctului interincisiv inferior are un aspect de ansamblu romboid."},{"id":"C","text":"Această analiză stă la baza procedeelor de înregistrare grafică a relației centrice."},{"id":"D","text":"Este esențială exclusiv pentru înțelegerea mișcărilor de propulsie."},{"id":"E","text":"Poate fi utilizată pentru programarea articulatoarelor."}],"correct":["B","C","E"],"pages":[186],"source":"set-2"},{"id":"set2-ywkYoZ-3","fingerprint":"16b8f505648d241d","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce caracterizează mișcarea Bennett a condilului pivotant (de partea lucrătoare)?","options":[{"id":"A","text":"Este un traseu foarte rar întâlnit, considerat adesea un artefact de înregistrare."},{"id":"B","text":"Traiectoria de deplasare este strict bidimensională, în direcție laterală și inferioară."},{"id":"C","text":"Are o valoare medie de 0.75 mm, iar programarea ei în articulator este indicată când depășește 2 mm."},{"id":"D","text":"Este o mișcare de rotație și translație înainte, în jos și medial."},{"id":"E","text":"Reprezintă o deplasare laterală exprimată în grade, cu valori între 7-30°."}],"correct":["C"],"pages":[186],"source":"set-2"},{"id":"set2-ApG5q3G1","fingerprint":"aa6410dc4729a059","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Cum este definit unghiul lui Bennett?","options":[{"id":"A","text":"Unghiul format de traiectoria de deplasare a condilului orbitant cu planul orizontal în mișcarea de lateralitate."},{"id":"B","text":"Unghiul format de traiectoria condilului pivotant cu planul sagital în mișcarea de propulsie."},{"id":"C","text":"Unghiul format de traiectoria de deplasare a condilului orbitant cu planul sagital în mișcarea de lateralitate."},{"id":"D","text":"Diferența de angulație dintre traiectoria condilului în propulsie și cea în lateralitate, măsurată în plan sagital."},{"id":"E","text":"Valoarea medie a deplasării laterale a condilului lucrător, exprimată în grade."}],"correct":["C"],"pages":[186],"source":"set-2"},{"id":"set2-4c2pz2bq","fingerprint":"4ad47469f995536f","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce reprezintă \"conul lui Guichet\" în gnatologie?","options":[{"id":"A","text":"Configurația peretelui median al articulației temporomandibulare."},{"id":"B","text":"Traiectoria tridimensională de deplasare a condilului orbitant în mișcarea de lateralitate."},{"id":"C","text":"Unghiul format între traiectoriile de laterotruzie și mediotruzie pe fețele ocluzale."},{"id":"D","text":"Aria mișcărilor funcționale în plan orizontal, care are o formă romboidală."},{"id":"E","text":"Ansamblul traiectoriei tridimensionale de deplasare a condilului pivotant."}],"correct":["E"],"pages":[186],"source":"set-2"},{"id":"set2-8wwzOfLm","fingerprint":"38499950ac504127","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt afirmațiile adevărate cu privire la unghiul lui Fischer?","options":[{"id":"A","text":"Are valori cuprinse în general între 7-30°."},{"id":"B","text":"Este generat de diferența de angulație între traiectoria condilului în propulsie și cea în lateralitate de partea opusă, înregistrată în plan sagital."},{"id":"C","text":"Se mai numește și traiectoria mediană Marxkors."},{"id":"D","text":"Valoarea sa reală este mai mică, valoarea acreditată de 10° rezultând din faptul că înregistrarea se face la distanță."},{"id":"E","text":"Se înregistrează în plan orizontal și este influențat de laxitatea capsulei ATM."}],"correct":["B","C","D"],"pages":[186],"source":"set-2"},{"id":"set2-xIVicW2W","fingerprint":"7556fe58917e6cdf","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care este influența unghiului Bennett și a distanței intercondiliene asupra morfologiei ocluzale?","options":[{"id":"A","text":"Cu cât unghiul lui Bennett este mai mare, cu atât relieful ocluzal trebuie să fie mai accentuat."},{"id":"B","text":"Distanța intercondiliană influențează direct valoarea unghiului lui Fischer."},{"id":"C","text":"Cu cât distanța intercondiliană este mai mare, cu atât unghiul delimitat pe fețele ocluzale ale dinților între traiectoriile de laterotruzie și mediotruzie va fi mai mic."},{"id":"D","text":"Cu cât unghiul lui Bennett este mai mare, cu atât concavitatea fețelor palatinale ale frontalilor superiori trebuie să fie mai accentuată."},{"id":"E","text":"Cu cât distanța intercondiliană este mai mare, cu atât unghiul dintre traiectoriile de laterotruzie și mediotruzie pe fețele ocluzale va fi mai mare."}],"correct":["C","D"],"pages":[186],"source":"set-2"},{"id":"set2-70usKKQ9","fingerprint":"39b1c6654c62022d","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"De ce este importantă, din punct de vedere aplicativ, evaluarea primilor 4 mm de deplasare a condilului orbitant?","options":[{"id":"A","text":"Pentru că traseul imediat, un artefact de înregistrare, se produce doar după 4 mm de deplasare."},{"id":"B","text":"Deoarece în această limită se înregistrează unghiul lui Fischer."},{"id":"C","text":"Deoarece laxitatea capsulei ATM permite mișcări doar în acest interval."},{"id":"D","text":"Pentru că în acest interval se manifestă integral mișcarea Bennett de partea lucrătoare."},{"id":"E","text":"Deoarece dincolo de această limită arcadele dentare nu se mai află în contact."}],"correct":["E"],"pages":[186],"source":"set-2"},{"id":"set2-tFeR83vg","fingerprint":"8dec1075b3fceab0","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt caracteristicile relațiilor de \"long centric\" și \"point centric\"?","options":[{"id":"A","text":"Atât \"long centric\", cât și \"point centric\" descriu traiectoria de la RC la propulsie maximă."},{"id":"B","text":"În \"point centric\", există un decalaj oblic descendent spre RC de 0.5 mm."},{"id":"C","text":"\"Long centric\" poate implica un decalaj strict orizontal sau unul oblic descendent spre RC, de 0.5 mm, între IM și RC."},{"id":"D","text":"În \"point centric\", punctele care reprezintă relația centrică (RC) și intercuspidarea maximă (IM) se suprapun."},{"id":"E","text":"\"Long centric\" se caracterizează prin suprapunerea punctelor ce reprezintă RC și IM pe diagramă."}],"correct":["C","D"],"pages":[186],"source":"set-2"},{"id":"set2-TtnJhb1a","fingerprint":"011f435789d889f1","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următorii parametri influențează morfologia ocluzală și a feței palatinale a dinților frontali superiori?","options":[{"id":"A","text":"Curba transversală de ocluzie"},{"id":"B","text":"Direcția traiectoriilor protruzive"},{"id":"C","text":"Înclinaţia pantei tuberculului articular"},{"id":"D","text":"Mişcările funcţionale ale punctului interincisiv"},{"id":"E","text":"Gradul de overbite şi overjet"}],"correct":["A","C","E"],"pages":[187],"source":"set-2"},{"id":"set2-kIqqO7HF","fingerprint":"1e42c895010aa3ec","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"În ce mod influențează un unghi mare între planul ocluzal și panta tuberculului articular morfologia dinților laterali?","options":[{"id":"A","text":"Influența este inversă."},{"id":"B","text":"Relieful ocluzal trebuie să fie mai șters."},{"id":"C","text":"Concavitățile de pe fețele palatinale ale frontalilor superiori sunt mai accentuate."},{"id":"D","text":"Apar interferențe lucrătoare și nelucrătoare."},{"id":"E","text":"Cuspizii dinților laterali pot fi mai înalți."}],"correct":["E"],"pages":[187],"source":"set-2"},{"id":"set2-aID5cdrT","fingerprint":"c72fe7b28542fb57","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce descrie aspectul urmelor de 'degete de pasăre' de pe suprafețele ocluzale?","options":[{"id":"A","text":"Reproducerea mișcărilor mandibulei în plan frontal."},{"id":"B","text":"Ansamblul traiectoriilor mediotruzive, laterotruzive și protruzive trasate de cuspidul de sprijin."},{"id":"C","text":"Urmele lăsate exclusiv la nivelul dinților arcadei superioare."},{"id":"D","text":"Doar traiectoriile mediotruzive și laterotruzive din timpul mișcării Bennett."},{"id":"E","text":"Traiectoria protruzivă a cuspidului de sprijin la nivel mandibular, orientată anterior."}],"correct":["B"],"pages":[187],"source":"set-2"},{"id":"set2-_Yl49Zcu","fingerprint":"f7ab4c1a1f19f4ad","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt riscurile sau dezavantajele utilizării unui ocludator simplu pentru realizarea reabilitărilor protetice de mare amploare?","options":[{"id":"A","text":"Determinarea pivotării inferioare a condililor mandibulari din poziția stabilă ortopedic."},{"id":"B","text":"Necesitatea unor ajustări ocluzale laborioase ale lucrărilor protetice în cavitatea orală."},{"id":"C","text":"Apariția contactelor premature în zonele distale în timpul mișcării de închidere."},{"id":"D","text":"Programarea inadecvată a unghiului Bennett."},{"id":"E","text":"Imposibilitatea montării modelului maxilar la brațul superior al dispozitivului."}],"correct":["A","B","C"],"pages":[187],"source":"set-2"},{"id":"set2-ca2gQHZK","fingerprint":"2d7b9b7e58a9e4f7","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care este scopul principal pentru care se utilizează arcul facial de transfer?","options":[{"id":"A","text":"Pentru a poziționa modelul maxilar pe articulator într-un raport corect față de baza craniului."},{"id":"B","text":"Pentru a evita utilizarea unui articulator programabil."},{"id":"C","text":"Pentru a programa panta tuberculului articular pe un articulator."},{"id":"D","text":"Pentru a înregistra grafic unghiul simfizar, numit și 'gotic'."},{"id":"E","text":"Pentru a analiza deplasările mandibulei în plan frontal."}],"correct":["A"],"pages":[187],"source":"set-2"},{"id":"set2-RQw4CGRb","fingerprint":"c4db9ce764e78a3d","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care sunt principalele tipuri constructive de arcuri faciale de transfer?","options":[{"id":"A","text":"Auriculare, pretragiene și glabelare."},{"id":"B","text":"FAG și Dentatus."},{"id":"C","text":"Arcon și non-arcon."},{"id":"D","text":"Pantografice și axiografice."},{"id":"E","text":"Cinematice, arbitrare și posturale."}],"correct":["E"],"pages":[188],"source":"set-2"},{"id":"set2-WaSfn6Co","fingerprint":"4233c9c4a9fc8668","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce criteriu stă la baza divizării arcurilor faciale arbitrare în cele două subtipuri principale?","options":[{"id":"A","text":"Necesitatea utilizării unui indicator pentru punctul infraorbital."},{"id":"B","text":"Tipul de înregistrări utilizate: poziționale sau grafice."},{"id":"C","text":"Modalitatea de fixare în zona articulațiilor temporomandibulare."},{"id":"D","text":"Arcada pe care se fixează furca ocluzală, maxilară sau mandibulară."},{"id":"E","text":"Compatibilitatea cu articulatoare de tip arcon sau non-arcon."}],"correct":["C"],"pages":[188],"source":"set-2"},{"id":"set2-BAE99jkM","fingerprint":"ebabe0d75f58acb3","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele afirmații descriu corect arcul facial postural propus de Ferrarrio et al.?","options":[{"id":"A","text":"Se poziționează pe baza depistării axei balama reale a pacientului."},{"id":"B","text":"Are ca scop orientarea tridimensională a planului de ocluzie în poziția naturală a capului."},{"id":"C","text":"Necesită obligatoriu un punct de sprijin glabelar pentru orientare."},{"id":"D","text":"Poziția 3D a planului de ocluzie este apreciată direct in vivo și apoi transferată la articulator."},{"id":"E","text":"Se utilizează asociat cu un dispozitiv electromagnetic tridimensional numit Gnatologic System."}],"correct":["B","D","E"],"pages":[188],"source":"set-2"},{"id":"set2-MgRuzdAY","fingerprint":"90d98a12512d4c2c","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele repere și componente sunt utilizate în procesul de fixare și orientare a arcurilor faciale de transfer?","options":[{"id":"A","text":"Conductele auditive externe, pentru arcurile prevăzute cu olive auriculare."},{"id":"B","text":"O linie situată pretragian la 10-13 mm, între tragus și punctul infraorbital."},{"id":"C","text":"Unghiul simfizar-gotic, pentru a stabili planul de referință."},{"id":"D","text":"Punctul glabelar (nasion), ca punct de sprijin pentru arcurile cu fixare auriculară."},{"id":"E","text":"Furca ocluzală, pentru a solidariza arcul la arcada dentară."}],"correct":["A","B","D","E"],"pages":[188],"source":"set-2"},{"id":"set2-eQjZdqB8","fingerprint":"0c238f3be7b0f216","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Cum sunt clasificate, în general, simulatoarele cinematicii mandibulare?","options":[{"id":"A","text":"Arcon, non-arcon, Gysi Simplex și Condylator Gerber."},{"id":"B","text":"Clasa I (ocludatoare), clasa a II-a (arcon), clasa a III-a (non-arcon) și clasa a IV-a (programabile)."},{"id":"C","text":"Tip balama, cu valori medii, semi-programabile și programabile."},{"id":"D","text":"Ocludatoare (clasa I), articulatoare neadaptabile (clasa a II-a), parțial adaptabile și în întregime adaptabile (clasele a III-a și a IV-a)."},{"id":"E","text":"Cinematice, arbitrare, posturale și pantografice."}],"correct":["D"],"pages":[188],"source":"set-2"},{"id":"set2-KGe3DEBM","fingerprint":"453e074ebccc1d7f","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care este diferența principală legată de unghiul Balkwill între un articulator semi-adaptabil de tip arcon și unul de tip non-arcon?","options":[{"id":"A","text":"La articulatorul arcon, unghiul Balkwill rămâne nemodificat la deschidere, în timp ce la non-arcon acesta se modifică."},{"id":"B","text":"Unghiul Balkwill determină erori ocluzale la ambele tipuri de articulatoare, dar mai ales în zona molară."},{"id":"C","text":"Rezultatele protetice sunt aproape identice, deși unghiul Balkwill este relevant doar pentru articulatoarele arcon."},{"id":"D","text":"La articulatorul non-arcon, unghiul Balkwill rămâne nemodificat la deschidere, spre deosebire de cel arcon, unde se modifică."},{"id":"E","text":"Articulatoarele arcon nu permit modificarea unghiului Balkwill, în timp ce cele non-arcon sunt programabile în acest sens."}],"correct":["A"],"pages":[188],"source":"set-2"},{"id":"set2-VNopf7wC","fingerprint":"3efecd7a14ab4007","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce consecință clinică poate avea modificarea unghiului Balkwill la deschiderea unui articulator de tip non-arcon?","options":[{"id":"A","text":"Necesitatea de a recurge exclusiv la axiografie pentru programarea articulatorului."},{"id":"B","text":"Apariția unor erori la nivel ocluzal, în special în zona premolarilor, la utilizarea înregistrărilor în propulsie."},{"id":"C","text":"O uzură accelerată a elementelor condiliene ale simulatorului."},{"id":"D","text":"Rezultate protetice fundamental diferite față de cele obținute cu un articulator de tip arcon."},{"id":"E","text":"Imposibilitatea de a folosi un arc facial cu fixare auriculară."}],"correct":["B"],"pages":[188],"source":"set-2"},{"id":"set2-uIrAh6i_","fingerprint":"61d440489e7c3c22","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele sunt metode valide pentru programarea articulatoarelor conform cinematicii mandibulare a unui pacient?","options":[{"id":"A","text":"Înregistrări poziționale ale mandibulei în intercuspidare maximă, propulsie și lateralitate."},{"id":"B","text":"Poziționarea modelelor cu ajutorul unui arc facial postural."},{"id":"C","text":"Înregistrări grafice intraorale, precum cea a unghiului simfizar-gotic."},{"id":"D","text":"Axiografie temporo-mandibulară, fie mecanică, fie electronică computerizată."},{"id":"E","text":"Selectarea unor valori medii pre-setate, specifice articulatoarelor neadaptabile."}],"correct":["A","C","D"],"pages":[188],"source":"set-2"},{"id":"set2-uRaZbKSM","fingerprint":"82faf73b84bb723f","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Ce parametri specifici ai mișcării mandibulare pot fi determinați prin axiografie temporo-mandibulară în vederea programării unui articulator?","options":[{"id":"A","text":"Tiparul traseului condililor mandibulari nelucrători în mișcarea de lateralitate."},{"id":"B","text":"Înclinația pantei tuberculiene."},{"id":"C","text":"Poziția 3D a planului de ocluzie în poziția naturală a capului."},{"id":"D","text":"Unghiul Balkwill, pentru a alege între un articulator arcon și non-arcon."},{"id":"E","text":"Valoarea unghiului și a mișcării Bennett."}],"correct":["A","B","E"],"pages":[188],"source":"set-2"},{"id":"set2-CmAOQmTF","fingerprint":"2365a246c0566916","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt structurile musculare care alcătuiesc unitatea funcțională denumită „mecanism buccinator”?","options":[{"id":"A","text":"Mușchii buccinatori"},{"id":"B","text":"Mușchii masticatori ridicători ai mandibulei"},{"id":"C","text":"Mușchii constrictori superiori faringieni"},{"id":"D","text":"Mușchii orbiculari ai buzelor"},{"id":"E","text":"Musculatura intrinsecă a limbii"}],"correct":["A","C","D"],"pages":[175,176],"source":"set-2"},{"id":"set2-Q-KnAP4k","fingerprint":"d655fe44e123fc42","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care este rolul principal al contactului ocluzal în menținerea echilibrului interarcadic?","options":[{"id":"A","text":"Prevenirea migrării verticale a dinților sub formă de extruzie și egresiune"},{"id":"B","text":"Echilibrarea forțelor exercitate exclusiv de musculatura linguo-oro-facială"},{"id":"C","text":"Menținerea unei distanțe constante între dinții adiacenți pentru a preveni abraziunea proximală"},{"id":"D","text":"Facilitarea mezializării continue a dinților pe parcursul masticației"},{"id":"E","text":"Prevenirea vestibularizării dinților frontali maxilari în timpul deglutiției infantile"}],"correct":["A"],"pages":[175,176],"source":"set-2"},{"id":"set2-sVXQetDB","fingerprint":"43ee04df7bf7ccb2","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt fenomenele care pot apărea ca urmare a distrugerii suprafețelor aproximale ale dinților posteriori prin carie sau a întreruperii continuității arcadei prin extracții?","options":[{"id":"A","text":"Alterarea relațiilor ocluzale prin migrări dentare combinate verticale și orizontale"},{"id":"B","text":"Creșterea rezistenței osului alveolar la procesele de intruzie a dinților adiacenți"},{"id":"C","text":"Apariția migrărilor dentare sub forma basculărilor spre spațiul existent"},{"id":"D","text":"Accentuarea permanentă a tiparului unic de contact ocluzal al dinților restanți"},{"id":"E","text":"Apariția migrărilor dentare sub forma translațiilor spre spațiul existent"}],"correct":["A","C","E"],"pages":[175,176],"source":"set-2"},{"id":"set2-6KpehpTI","fingerprint":"f32f4f0043512d74","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"În dinamica forțelor care condiționează alinierea dentară pe arcade, ce desemnează conceptul de „culoar muscular” sau zonă neutră?","options":[{"id":"A","text":"Traiectoria de deplasare verticală și vestibulo-orală a dintelui în alveolă"},{"id":"B","text":"Direcția de basculare și translație a dinților spre un spațiu edentat"},{"id":"C","text":"Aria de intercuspidare care previne migrarea verticală a dinților sub formă de egresiune"},{"id":"D","text":"Spațiul obținut prin abrazarea continuă a suprafețelor dentare proximale în timpul masticației"},{"id":"E","text":"O poziție în care forțele dezvoltate de grupul muscular intern se află în echilibru cu cele dezvoltate de grupul muscular extern"}],"correct":["E"],"pages":[175,176],"source":"set-2"},{"id":"set2-uv5e2Ofx","fingerprint":"fd85ce83315c615d","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care dintre următoarele caracteristici referitoare la înclinarea dentară și curburile de ocluzie este corectă?","options":[{"id":"A","text":"Curba lui Wilson este descrisă prin observarea arcadelor dentare exclusiv din normă laterală."},{"id":"B","text":"La mandibulă, dinții posteriori prezintă o ușoară înclinare vestibulară, participând la formarea curbei lui Wilson."},{"id":"C","text":"La maxilar, atât dinții anteriori, cât și cei posteriori prezintă o înclinare spre mezial."},{"id":"D","text":"În cadrul maxilarului, axele dinților posteriori sunt orientate spre distal."},{"id":"E","text":"Curba sagitală de ocluzie a lui Spee este concavă la nivelul maxilarului și convexă la mandibulă."}],"correct":["D"],"pages":[176],"source":"set-2"},{"id":"set2-i1OYlrv_","fingerprint":"1320da79475e20b6","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt reperele geometrice și conceptele gnatologice descrise în cadrul teoriilor relațiilor interarcade?","options":[{"id":"A","text":"Sfera imaginară descrisă de teoria lui Monson are raza de 10-11 cm."},{"id":"B","text":"Valoarea unghiului format de reperele triunghiului Balkwill este cuprinsă între 30 și 35 de grade."},{"id":"C","text":"Triunghiul Balkwill este delimitat de latura triunghiului Bonwill și de planul de ocluzie."},{"id":"D","text":"Centrul sferei lui Monson este localizat la nivelul suprafețelor ocluzale ale dinților posteriori."},{"id":"E","text":"Curbele Spee și Monson se înscriu pe sfera imaginară descrisă în teoria lui Monson."}],"correct":["A","C","E"],"pages":[176],"source":"set-2"},{"id":"set2-QLlK5L_N","fingerprint":"b5e85bf88f67c982","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele afirmații descriu riguros structura și proporțiile tablei ocluzale?","options":[{"id":"A","text":"Suprafața ocluzală situată în afara tablei ocluzale este formată în mod exclusiv de versanții interni cuspidieni."},{"id":"B","text":"Structura tablei ocluzale suportă o proporție minoră a forțelor de masticație preluate de arcadă."},{"id":"C","text":"Dimensiunea tablei ocluzale reprezintă aproximativ 50-60% din dimensiunea vestibulo-orală a dinților posteriori."},{"id":"D","text":"Tabla ocluzală include aria anatomică cuprinsă între marginile incizale ale dinților anteriori și cuspizii dinților posteriori."},{"id":"E","text":"Tabla ocluzală reprezintă aria dentară cuprinsă între vârfurile cuspizilor vestibulari și orali ai dinților posteriori."}],"correct":["C","E"],"pages":[177],"source":"set-2"},{"id":"set2-UTszeJWK","fingerprint":"0a47da094418ac56","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care este factorul biomecanic principal care dictează necesitatea curburilor planurilor ocluzale ale arcadelor dentare?","options":[{"id":"A","text":"Mărimea unghiului de 22-20 de grade format strict de intersecția planului de ocluzie cu axele dinților anteriori."},{"id":"B","text":"Proporția tablei ocluzale care reprezintă aproximativ 20-30% din dimensiunea vestibulo-orală a dinților."},{"id":"C","text":"Funcționarea majoritară a articulațiilor temporo-mandibulare cu mișcări complet identice și simultane."},{"id":"D","text":"Mișcările mandibulare complexe, caracterizate de centre de rotație condiliene aflate în deplasare constantă."},{"id":"E","text":"Convexitatea pronunțată a curbei sagitale la nivelul mandibulei, care limitează contactele dentare funcționale."}],"correct":["D"],"pages":[176],"source":"set-2"},{"id":"set2-TVUoFQSZ","fingerprint":"e1e46d93b2308218","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele afirmații descriu corect caracteristicile schemei ocluzale gnatologice (organice)?","options":[{"id":"A","text":"La nivelul dinților anteriori se evidențiază inocluzia, pentru asigurarea protecției mutuale în propulsie."},{"id":"B","text":"Intercuspidarea maximă coincide cu relația centrică (point centric)."},{"id":"C","text":"Deglutiția se efectuează în intercuspidare maximă."},{"id":"D","text":"Mișcarea de lateralitate se realizează cu protecție canină pe partea activă."},{"id":"E","text":"Îmbinarea mecanică dintre cele două arcade antagoniste este obținută prin contactarea de tip cuspid-suprafață."}],"correct":["A","B","D"],"pages":[178],"source":"set-2"},{"id":"set2-xtuBsTsS","fingerprint":"820bc5fc5f7368c3","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele enunțuri descriu corect rolul și caracteristicile cuspizilor inactivi?","options":[{"id":"A","text":"Aceștia anulează componentele orizontale ale forțelor ocluzale, fiind cunoscuți și sub denumirea de cuspizi de echilibru."},{"id":"B","text":"Versanții lor de ghidaj asigură conducerea mandibulei exclusiv în mișcările de propulsie."},{"id":"C","text":"Realizează contacte multipoziționale prin care se menține dimensiunea verticală de ocluzie."},{"id":"D","text":"Fiecare cuspid inactiv realizează contact cu multiple versante cuspidiene antagoniste."},{"id":"E","text":"Aceștia sunt reprezentați de cuspizii vestibulari la maxilar și cei linguali la mandibulă."}],"correct":["A","E"],"pages":[178],"source":"set-2"},{"id":"set2-o3Yb3E4K","fingerprint":"a8fec2a69ce71f0f","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Referitor la elementele de morfologie dentară cu rol de sprijin al ocluziei, care dintre următoarele reprezintă stopuri ocluzale de clasa a III-a?","options":[{"id":"A","text":"Marginile incizale ale incisivilor inferiori."},{"id":"B","text":"Cuspizii centro-vestibulari ai molarilor primi inferiori."},{"id":"C","text":"Cuspizii palatinali ai premolarilor și molarilor superiori."},{"id":"D","text":"Marginile libere ale caninilor inferiori."},{"id":"E","text":"Cuspizii vestibulari ai premolarilor și molarilor inferiori."}],"correct":["C"],"pages":[177],"source":"set-2"},{"id":"set2-vVF6w6Gv","fingerprint":"b4675a851560687b","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Privind rapoartele de ocluzie și relațiile dento-dentare interarcade, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Lungimea medie a arcului maxilar este de 128 mm, fiind superioară lungimii arcului mandibular."},{"id":"B","text":"Decalajul sagital dintre fețele palatinale ale frontalilor superiori și cele vestibulare ale frontalilor inferiori poartă denumirea de overjet."},{"id":"C","text":"Gradul de supraacoperire incisivă în plan vertical este desemnat prin termenul de overbite."},{"id":"D","text":"Diferența de lungime dintre cele două arcuri rezultă din spațiul mai mare mezio-distal pe care îl ocupă incisivul central inferior."},{"id":"E","text":"În sens sagital, dinții mandibulari sunt poziționați mai distal comparativ cu dinții maxilari, într-o ocluzie normală."}],"correct":["A","B","C"],"pages":[178],"source":"set-2"},{"id":"set2-tx0svXJF","fingerprint":"332d9e581dc7cdd4","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele elemente caracterizează schema ocluzală denumită „freedom in centric”?","options":[{"id":"A","text":"Ghidajul exclusiv canin pe partea lucrătoare în mișcarea de lateralitate."},{"id":"B","text":"Existența unei zone de libertate a cuspidului de sprijin pe suprafața ocluzală antagonistă de 0,5-1 mm, anterioară poziției de contactare în relație centrică."},{"id":"C","text":"Existența unei libertăți de mișcare transversală a cuspidului de sprijin, denumită „wide centric”."},{"id":"D","text":"Deglutiția se desfășoară exclusiv în relația centrică a mandibulei."},{"id":"E","text":"Necesitatea mecanică a unei contactări de tip cuspid-suprafață."}],"correct":["B","C","E"],"pages":[178],"source":"set-2"},{"id":"set2-Mzam7qir","fingerprint":"5bcd786bbe6f7987","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care este caracteristica morfologică și funcțională principală a schemei ocluzale bazate pe conceptul „freedom in centric”?","options":[{"id":"A","text":"Realizarea unor contacte dentare în suprafață între toți cuspizii și fosele antagoniste."},{"id":"B","text":"Modelarea fosei antagoniste sub forma unei eminențe convexe pentru a limita mișcările de lateralitate."},{"id":"C","text":"Realizarea contactelor exclusive la nivelul cuspizilor inactivi, lăsând cuspizii activi în inocluzie."},{"id":"D","text":"Rigidizarea musculaturii masticatorii și a articulațiilor temporo-mandibulare pentru a preveni iregularitățile ocluzale."},{"id":"E","text":"Plasarea cuspizilor inactivi în ușoară inocluzie, contactele punctiforme realizându-se de tip cuspid activ-fosă antagonistă."}],"correct":["E"],"pages":[178],"source":"set-2"},{"id":"set2-HgUb-MiF","fingerprint":"af1da46788c06ce0","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt indicațiile și avantajele ocluziei „lingualizate” (ocluzia cu contact cuspidian palatinal) în reabilitarea orală?","options":[{"id":"A","text":"Existența unor diferențe de mărime ale arcadelor dentare secundare proceselor de resorbție și atrofie."},{"id":"B","text":"Protezarea pe implanturi, deoarece determină reducerea sau eliminarea forțelor laterale nocive."},{"id":"C","text":"Protezarea exclusiv prin abordări convenționale fixe, fiind contraindicată în protetica pe implanturi."},{"id":"D","text":"Tratamentul edentației parțiale terminale prin proteze mobilizabile, pentru a diminua solicitările mecanice asupra șeilor terminale."},{"id":"E","text":"Situațiile clinice caracterizate de resorbții minime ale crestelor edentate, unde forțele laterale sunt benefice."}],"correct":["A","B","D"],"pages":[179],"source":"set-2"},{"id":"set2-ouBtd51j","fingerprint":"7fc7ef8c0db5d5a6","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt afirmațiile adevărate privind criteriile ocluziei funcționale descrise de Korber?","options":[{"id":"A","text":"Factorul continuității suprafețelor ocluzale este asigurat prin prezența edentațiilor intercalate."},{"id":"B","text":"Factorul cantitativ presupune existența contactelor dentare multipoziționale."},{"id":"C","text":"Factorul forță reprezintă concentrarea solicitărilor ocluzale la nivelul dinților frontali."},{"id":"D","text":"Factorul timp este caracterizat de obținerea unor contacte dentare simultane."},{"id":"E","text":"Factorul de mișcare implică alunecarea dento-dentară fără obstacole."}],"correct":["B","D","E"],"pages":[179],"source":"set-2"},{"id":"set2-jQBY7NYY","fingerprint":"1e6141f4a0e6b86a","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt caracteristicile parametrilor temporali determinați în cadrul evaluării computerizate a ocluziei dentare?","options":[{"id":"A","text":"Timpul de ocluzie fiziologic trebuie să aibă valori cuprinse între 0.4 și 0.6 secunde."},{"id":"B","text":"Timpul de ocluzie reprezintă intervalul scurs de la apariția primei contactări dentare până la realizarea intercuspidării maxime."},{"id":"C","text":"Timpul de dezocluzie măsoară durata necesară separării arcadelor dentare exclusiv în mișcarea de deschidere a gurii."},{"id":"D","text":"Prelungirea timpilor de ocluzie și dezocluzie constituie un factor predispozant pentru instalarea unei disfuncții craniomandibulare."},{"id":"E","text":"Timpul necesar dezocluziei dentare în mișcările de propulsie și lateralitate ale mandibulei trebuie să fie în mod normal sub 0.4 secunde."}],"correct":["B","D","E"],"pages":[179],"source":"set-2"},{"id":"set2-LuzbpRBo","fingerprint":"18b95bff0e0bff15","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Ce trăsături definesc schemele ocluzale moderne aplicate în reabilitările protetice fixe și mobile?","options":[{"id":"A","text":"Fosa antagonistă cuspidului activ este modelată concav pentru a permite traiectoriile protruzive și de mediotruzie."},{"id":"B","text":"Ocluzia lingualizată reduce forțele laterale nocive în protezarea pe implanturi."},{"id":"C","text":"Cuspizii inactivi sunt plasați în ocluzie strânsă pentru a stabiliza adaptarea musculară."},{"id":"D","text":"Permite adaptarea musculaturii masticatorii și a articulațiilor temporo-mandibulare la iregularitățile ocluzale."},{"id":"E","text":"Ocluzia cu contact cuspidian palatinal amplifică solicitările mecanice pe șeile terminale ale protezei parțiale mobilizabile."}],"correct":["A","B","D"],"pages":[178],"source":"set-2"},{"id":"set2-tTJpVjHx","fingerprint":"f10bfdd61d562969","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt caracteristicile și rolurile stopurilor ocluzale în relație centrică și în intercuspidare maximă în cadrul unei ocluzii funcționale?","options":[{"id":"A","text":"Previn migrările dentare."},{"id":"B","text":"Sunt stabile, simultane, asimetrice și multiple."},{"id":"C","text":"Dirijează solicitările ocluzale pe direcție orizontală."},{"id":"D","text":"Realizează uzura fiziologică a dinților."},{"id":"E","text":"Permit alunecarea mandibulei fără impacte."}],"correct":["A","D","E"],"pages":[179],"source":"set-2"},{"id":"set2-hM0KRIdw","fingerprint":"9d7f176c4f50fcde","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"În care dintre următoarele situații dinamica mandibulară trebuie să fie dominată de mișcări predominant verticale, limitând mișcările orizontale pentru a evita interferențele ocluzale?","options":[{"id":"A","text":"Existența unui ghidaj anterior abrupt."},{"id":"B","text":"Prezența unui ghidaj de grup realizat simultan de incisivi și pantele laterotrusive."},{"id":"C","text":"Efectuarea unei mișcări de propulsie susținută de o singură pereche de frontali antagoniști."},{"id":"D","text":"Situația în care panta tuberculului articular are o înclinație medie de 33 de grade."},{"id":"E","text":"Exprimarea unui tipar de morfologie ocluzală bazat pe conceptul busolei ocluzale."}],"correct":["A"],"pages":[179],"source":"set-2"},{"id":"set2-IMDlQ7Pn","fingerprint":"c9f7c785f98ad269","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele afirmații descriu corect contactele dento-dentare și interferențele ce apar în cursul mișcării de propulsie a mandibulei?","options":[{"id":"A","text":"Contactele care determină devieri ale mandibulei localizate în zona frontală se numesc interferențe pasive."},{"id":"B","text":"Orice contact dento-dentar apărut în zonele laterale în timp ce frontalii sunt în poziția cap la cap reprezintă un contact prematur nelucrător."},{"id":"C","text":"Susținerea poziției cap la cap de către un singur dinte frontal constituie un contact prematur lucrător."},{"id":"D","text":"Contactele localizate în zonele laterale sau distale care provoacă devieri mandibulare sunt denumite interferențe pasive."},{"id":"E","text":"Dinții cuspidați au un rol funcțional esențial în incizia alimentelor alături de dinții frontali."}],"correct":["B","C","D"],"pages":[180],"source":"set-2"},{"id":"set2-kdhfmOPa","fingerprint":"0a46a96f865011d1","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt particularitățile structurale și funcționale ale meniscului articular și ale zonei bilaminare în cadrul articulației temporo-mandibulare?","options":[{"id":"A","text":"Zona bilaminară are rolul de a facilita devierea mandibulei în timpul mișcării de propulsie."},{"id":"B","text":"Atașamentul posterior meniscal oferă un sprijin vascular hidrodinamic tridimensional pentru poziționarea condilo-meniscală."},{"id":"C","text":"Zona bilaminară este formată dintr-un strat superior elastic și unul inferior colagenic, lipsit de proprietăți elastice."},{"id":"D","text":"Meniscul articular prezintă o zonă centrală intens vascularizată și inervată pentru percepția presiunilor."},{"id":"E","text":"Meniscul articular transformă cele două suprafețe articulare în suprafețe congruente."}],"correct":["B","C","E"],"pages":[181],"source":"set-2"},{"id":"set2-hJH7hE_l","fingerprint":"1c2af7333e71db45","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următorii mușchi aparțin sistemului cranio-mandibular și acționează ca mușchi posturali stabilizatori ai articulației temporo-mandibulare, fiind activi în poziția de postură și la închiderea gurii?","options":[{"id":"A","text":"Porțiunea profundă a mușchiului maseter."},{"id":"B","text":"Fasciculul anterior al mușchiului temporal."},{"id":"C","text":"Fasciculul superior al mușchiului pterigoidian lateral."},{"id":"D","text":"Mușchiul pterigoidian medial."},{"id":"E","text":"Pântecul anterior al mușchiului digastric."}],"correct":["A","B","C"],"pages":[182],"source":"set-2"},{"id":"set2-LTGE-sSU","fingerprint":"b57ed16fc45dd0ce","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care dintre următoarele afirmații descriu corect poziția fiziologică de postură (repaus)?","options":[{"id":"A","text":"Se caracterizează prin prezența numărului maxim de contacte dento-dentare punctiforme."},{"id":"B","text":"Este o relație posturală în care grupele musculare antagoniste se află într-un relativ echilibru tonic."},{"id":"C","text":"Inocluzia fiziologică din poziția de postură variază direct proporțional cu dimensiunea verticală de ocluzie."},{"id":"D","text":"Spațiul liber interdentar în această poziție măsoară în mod normal între 1,25 și 1,5 mm."},{"id":"E","text":"Dimensiunea verticală a etajului inferior al feței în această poziție se numește dimensiune verticală de ocluzie (DVO)."}],"correct":["B"],"pages":[183],"source":"set-2"},{"id":"set2-enfzmdUT","fingerprint":"5002905f312fd4cd","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Poziția de relație centrică (RC) prezintă următoarele caracteristici:","options":[{"id":"A","text":"Este o poziție reproductibilă, condilii situându-se într-o poziție superioară limită."},{"id":"B","text":"Centrarea condililor se realizează exclusiv prin acțiunea mușchilor coborâtori ai mandibulei."},{"id":"C","text":"Din perspectivă anatomică, relația poate fi considerată de contact între două suprafețe osoase datorită grosimii reduse a porțiunii centrale a meniscului."},{"id":"D","text":"Mușchii care centrează condilii acționează prin vectori de forțe cu direcție postero-inferioară."},{"id":"E","text":"Condilii mandibulari sunt plasați pe pantele anterioare ale eminențelor articulare."}],"correct":["A","C"],"pages":[183],"source":"set-2"},{"id":"set2-x67pfdNU","fingerprint":"4faf4031e24be6d8","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt efectele și caracteristicile poziției de intercuspidare maximă (IM)?","options":[{"id":"A","text":"Orientează forțele ocluzale în axul lung al dinților."},{"id":"B","text":"Reprezintă o poziție diagnostică fundamentală în stabilirea rapoartelor intermaxilare."},{"id":"C","text":"Permite contracția simetrică, egală și maximă a mușchilor ridicători ai mandibulei."},{"id":"D","text":"Anulează și compensează forțele orizontale."},{"id":"E","text":"Presupune prezența unui spațiu liber interdentar obligatoriu de 1,2-4 mm."}],"correct":["A","C","D"],"pages":[183],"source":"set-2"},{"id":"set2-bcqKxiV0","fingerprint":"44617ec5e4d74d19","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Atunci când intercuspidarea maximă (IM) nu coincide cu poziția de relație centrică (RC), se pot întâlni următoarele situații patologice și fiziologice:","options":[{"id":"A","text":"„Wide centric”, care presupune o ușoară deplasare laterală a cuspidului de sprijin în foseta antagonistă."},{"id":"B","text":"Intercuspidarea maximă impusă, unde contactarea dento-dentară se produce în afara relației centrice și a „long centric”-ului."},{"id":"C","text":"„Long centric”, care reprezintă o alunecare transversală a mandibulei pe o suprafață de 1,25-1,5 mm."},{"id":"D","text":"„Freedom in centric”, caracterizată prin faptul că vârful cuspidului de sprijin este mai mare decât foseta antagonistă."},{"id":"E","text":"„Point centric”, situație regăsită în 85% din cazuri, în care IM nu coincide cu RC."}],"correct":["A","B"],"pages":[184],"source":"set-2"},{"id":"set2-39JEpzrf","fingerprint":"725c43c1717af1ac","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Triunghiul de toleranță ocluzală descris de Mario Spirgi prezintă următoarele dimensiuni și orientări:","options":[{"id":"A","text":"O bază de 2 mm orientată posterior și o înălțime de 1,25-1,5 mm."},{"id":"B","text":"O bază de 2 mm orientată posterior și o înălțime de 0,2-1,75 mm."},{"id":"C","text":"O bază de 2 mm orientată anterior și o înălțime de 0,2-1,75 mm."},{"id":"D","text":"O bază de 1,2-4 mm orientată posterior și o înălțime de 0,2 mm."},{"id":"E","text":"O bază de 1,25-1,5 mm orientată anterior și o înălțime de 2 mm."}],"correct":["B"],"pages":[184],"source":"set-2"},{"id":"set2-D4o3pqZH","fingerprint":"537e3cef44de0f36","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Ce patologii sau modificări morfologice sunt incluse în tipul IV al clasificării gnatologice a relațiilor ocluzale statice?","options":[{"id":"A","text":"Deplasarea condililor de la relația centrică verificabilă pentru a realiza intercuspidarea maximă."},{"id":"B","text":"Retruzia mandibulară progresivă."},{"id":"C","text":"Ocluzia deschisă frontală progresivă."},{"id":"D","text":"Intercuspidarea maximă în armonie cu o postură centrică adaptată."},{"id":"E","text":"Asimetria progresivă."}],"correct":["B","C","E"],"pages":[184],"source":"set-2"},{"id":"set2-QQZgJx24","fingerprint":"60ca0b2355620bc9","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele afirmații descriu stadiul clinic definit ca tipul III în clasificarea gnatologică a relațiilor ocluzale statice?","options":[{"id":"A","text":"Reprezintă o stare definitivă care se asociază cu o deformare articulară ireversibilă."},{"id":"B","text":"Starea este tranzitorie și tratabilă în scopul obținerii unei relații centrice sau a unei posturi centrice adaptate."},{"id":"C","text":"Condilii trebuie să se deplaseze de la postura centrică adaptată pentru a realiza intercuspidarea maximă."},{"id":"D","text":"Articulațiile nu pot accepta solicitări mecanice fără cauzarea disconfortului."},{"id":"E","text":"Relația centrică sau postura centrică adaptată nu poate fi verificată."}],"correct":["B","D","E"],"pages":[184],"source":"set-2"},{"id":"set2-dFrPH0IY","fingerprint":"173b4eadea4daf5b","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Ce caracterizează tipul I A în cadrul clasificării gnatologice a relațiilor ocluzale statice?","options":[{"id":"A","text":"Condilii se deplasează de la postura centrică adaptată pentru a realiza intercuspidarea maximă."},{"id":"B","text":"Relația ocluzală se află într-o fază de alterare continuă datorită instabilității articulare."},{"id":"C","text":"Condilii se deplasează de la relația centrică verificabilă pentru a realiza intercuspidarea maximă."},{"id":"D","text":"Intercuspidarea maximă este în armonie cu o postură centrică adaptată."},{"id":"E","text":"Intercuspidarea maximă se află în armonie cu o relație centrică verificabilă."}],"correct":["D"],"pages":[184],"source":"set-2"},{"id":"set2-ozPmOPsG","fingerprint":"0cec5f67dbdf11d2","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt afirmațiile care reflectă corect criteriile din clasificarea gnatologică a relațiilor ocluzale statice?","options":[{"id":"A","text":"Tipul II A necesită deplasarea condililor de la postura centrică adaptată pentru obținerea intercuspidării maxime."},{"id":"B","text":"Tipul III este caracterizat de o fază de alterare continuă secundară instabilității articulației temporo-mandibulare."},{"id":"C","text":"Tipul I presupune obținerea intercuspidării maxime în armonie cu o relație centrică verificabilă."},{"id":"D","text":"Tipul II implică deplasarea condililor de la o relație centrică verificabilă pentru a realiza intercuspidarea maximă."},{"id":"E","text":"Ocluzia habituală este sinonimă cu tipul IV datorită modificărilor asimetrice progresive."}],"correct":["A","C","D"],"pages":[184],"source":"set-2"},{"id":"set2-YzLQTLwq","fingerprint":"0464f4e80a2ef59b","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele manopere terapeutice sunt strict contraindicate în abordarea ocluzală a pacienților încadrați în tipurile I și II?","options":[{"id":"A","text":"Eliminarea interferențelor ocluzale"},{"id":"B","text":"Artroscopia articulației temporo-mandibulare"},{"id":"C","text":"Chirurgia articulației temporo-mandibulare"},{"id":"D","text":"Terapia prin gutiere pentru corectarea disfuncției articulare înaintea finalizării tratamentului ocluzal"},{"id":"E","text":"Injecțiile intraarticulare și spălăturile"}],"correct":["B","C","E"],"pages":[185],"source":"set-2"},{"id":"set2-UhmsssPP","fingerprint":"593fca0554f864ce","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care este motivul principal pentru care pacienții încadrați în tipul IV necesită cel mai complex plan de tratament?","options":[{"id":"A","text":"Necesitatea corectării disfuncției articulare înaintea finalizării tratamentului ocluzal"},{"id":"B","text":"Lipsa coincidenței dintre intercuspidarea maximă și relația centrică în timpul contracției"},{"id":"C","text":"Necesitatea utilizării miomonitorului pentru stimularea electrică unilaterală"},{"id":"D","text":"Prezența unei dureri musculare neamendate prin eliminarea interferențelor ocluzale"},{"id":"E","text":"Absența unei poziționări stabile a condililor la care să se raporteze ocluzia"}],"correct":["E"],"pages":[185],"source":"set-2"},{"id":"set2-aNPTGerr","fingerprint":"0edf39639a1556be","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt caracteristicile poziției miocentrice (Jankelson)?","options":[{"id":"A","text":"Presupune prezența obligatorie a unor afecțiuni intracapsulare asimptomatice"},{"id":"B","text":"Contactele ocluzale se realizează în zona long centric-ului, mai aproape de poziția de relație centrică"},{"id":"C","text":"Se determină utilizând un aparat specific denumit miomonitor"},{"id":"D","text":"Intercuspidarea maximă coincide perfect cu poziția de relație centrică"},{"id":"E","text":"Poate fi identificată prin stimularea electrică bilaterală a musculaturii ridicătoare a mandibulei"}],"correct":["B","C","E"],"pages":[185],"source":"set-2"},{"id":"set2-BUDOP9rH","fingerprint":"cb866abba57ef617","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"În abordarea terapeutică a pacienților încadrați în tipul III, care este conduita obligatorie premergătoare finalizării tratamentului ocluzal?","options":[{"id":"A","text":"Transformarea cazului în tipul IV prin intervenții chirurgicale"},{"id":"B","text":"Administrarea exclusivă a agenților medicamentoși miorelaxanți"},{"id":"C","text":"Stimularea electrică bilaterală a musculaturii coborâtoare a mandibulei"},{"id":"D","text":"Corectarea disfuncției articulației temporo-mandibulare"},{"id":"E","text":"Excluderea diagnosticului de fibromialgie ca primă etapă"}],"correct":["D"],"pages":[185],"source":"set-2"},{"id":"set2-yfyLt9-y","fingerprint":"ee2f7c6bfa14e3ea","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Ce trăsături definesc tabloul clinic și evoluția tipurilor I, I A, II și II A?","options":[{"id":"A","text":"Terapia prin gutiere ocluzale este utilizată frecvent ca abordare de primă intenție în tipurile I și II"},{"id":"B","text":"Prin corectarea ocluziei, tipurile II și II A sunt reversibile în tipul I sau I A"},{"id":"C","text":"Corectarea ocluziei transformă ireversibil tipurile I și I A în tipul IV"},{"id":"D","text":"Tipurile II și II A prezintă un prognostic excelent prin eliminarea interferențelor ocluzale"},{"id":"E","text":"Tipurile I și I A se caracterizează prin lipsa disconfortului muscular chiar și la forțe mari de contracție"}],"correct":["B","D","E"],"pages":[184],"source":"set-2"},{"id":"set2-Gs-VqdFU","fingerprint":"3c94e591f29c5f32","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele tipuri de mișcări mandibulare se încadrează în clasificarea realizată după criteriul combinării mișcărilor?","options":[{"id":"A","text":"Antero-laterale"},{"id":"B","text":"Sagitale"},{"id":"C","text":"De deschidere și propulsie"},{"id":"D","text":"Funcționale"},{"id":"E","text":"De deschidere și lateralitate"}],"correct":["A","C","E"],"pages":[185],"source":"set-2"},{"id":"set2-lAephsA5","fingerprint":"92a026c671029c03","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Ce caracteristici prezintă diagrama lui Posselt la analiza cinematicii mandibulare în plan sagital?","options":[{"id":"A","text":"Condilii mandibulei parcurg de-a lungul eminenței articulare o traiectorie sub forma unui cerc complet cu raza de 10-15 mm."},{"id":"B","text":"Situația de „point centric” se caracterizează printr-un decalaj strict orizontal între intercuspidarea maximă și relația centrică."},{"id":"C","text":"Punctul interincisiv inferior parcurge o distanță de 4 mm de la poziția de relație centrică la cea de cap la cap."},{"id":"D","text":"Distanța parcursă de punctul interincisiv inferior de la poziția de relație centrică la propulsia maximă este de 10 mm."},{"id":"E","text":"Situația de „long centric” presupune suprapunerea perfectă a punctelor care reprezintă relația centrică și intercuspidarea maximă."}],"correct":["C","D"],"pages":[185],"source":"set-2"},{"id":"set2-D6Kp1lhy","fingerprint":"65200f00984da01e","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la analiza generală a cinematicii mandibulare?","options":[{"id":"A","text":"Imaginea spațială tridimensională a ariei de mișcare a punctului interincisiv inferior are o formă caracteristică de bicuspidoid."},{"id":"B","text":"Mișcările limită sunt reduse la mișcări funcționale prin acțiunea musculaturii mobilizatoare a mandibulei și a ligamentelor articulațiilor temporomandibulare."},{"id":"C","text":"Deplasarea punctului interincisiv superior este folosită ca reper pentru analiza în toate cele trei planuri spațiale."},{"id":"D","text":"Mișcările funcționale din timpul masticației și fonației au o amplitudine identică cu cea a mișcărilor limită."},{"id":"E","text":"Traiectoria condiliană pe eminența articulară face parte dintr-un cerc imaginar cu raza de 15 mm."}],"correct":["A","B"],"pages":[185],"source":"set-2"},{"id":"set2-t44VUBXR","fingerprint":"9c54f943c9f59d68","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Care este particularitatea traiectoriei condiliene de la poziția de relație centrică la cea de propulsie maximă?","options":[{"id":"A","text":"Se desfășoară sub forma unui cerc complet cu raza de 10-15 mm."},{"id":"B","text":"Este determinată exclusiv de un decalaj strict orizontal între relația centrică și intercuspidarea maximă."},{"id":"C","text":"Înscrie o traiectorie de 4 mm, identică cu distanța de la poziția de relație centrică la cea de cap la cap."},{"id":"D","text":"Parcurge de-a lungul eminenței articulare o distanță de 10-15 mm sub forma unui semicerc."},{"id":"E","text":"Reprezintă o mișcare strict verticală cu o amplitudine de 20 mm."}],"correct":["D"],"pages":[186],"source":"set-2"},{"id":"set2-O2XZMytw","fingerprint":"d54c6d675503d31e","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următorii parametri anatomici și cinematici impun realizarea unui relief ocluzal mai șters al dinților laterali?","options":[{"id":"A","text":"O curbă sagitală de ocluzie mai pronunțată."},{"id":"B","text":"O înclinație mai mică a pantei tuberculului articular."},{"id":"C","text":"Un unghi crescut între planul ocluzal și panta tuberculului articular."},{"id":"D","text":"O valoare crescută a unghiului lui Bennett."},{"id":"E","text":"O distanță intercondiliană redusă."}],"correct":["A","B","D"],"pages":[187],"source":"set-2"},{"id":"set2-0AjnFj9h","fingerprint":"e136e283a8353222","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"În cursul mișcării de lateralitate a mandibulei, condilul orbitant prezintă o serie de particularități cinematice. Care dintre afirmațiile următoare referitoare la acesta este adevărată?","options":[{"id":"A","text":"Execută o mișcare de rotație și translație înainte, în jos și lateral."},{"id":"B","text":"Traiectoria sa formează cu planul sagital unghiul Bennett, cu valori în general cuprinse între 7-30°."},{"id":"C","text":"Evaluarea deplasării sale este relevantă clinic exclusiv dincolo de primii 4 mm ai traseului."},{"id":"D","text":"Traseul său imediat este o constantă fiziologică, evidențiind angrenarea completă a ansamblului menisc-condil."},{"id":"E","text":"Realizează o deplasare laterală în cavitatea glenoidă, recunoscută în gnatologie sub denumirea de mișcare Bennett."}],"correct":["B"],"pages":[186],"source":"set-2"},{"id":"set2-lpp3GrDG","fingerprint":"6652cc592bad2d96","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Referitor la cinematica condilului pivotant și a celui orbitant, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Mișcarea Bennett trebuie programată în articulator doar atunci când prezintă valori strict sub 1,5 mm."},{"id":"B","text":"Valoarea reală a unghiului lui Fisher depășește constant 10°, unghiurile mai mici fiind obținute doar prin înregistrarea la distanță pe pantograf."},{"id":"C","text":"Unghiul lui Fisher rezultă din diferența de angulație între traiectoria în propulsie și cea în lateralitate de partea opusă, pe aceeași plăcuță axiografică."},{"id":"D","text":"Traiectoria tridimensională de deplasare a condilului lucrător se înscrie într-un spațiu definit ca „conul lui Guichet”."},{"id":"E","text":"Mișcarea Bennett reprezintă deplasarea laterală a condilului lucrător și este, în medie, de 0,75 mm."}],"correct":["C","D","E"],"pages":[186],"source":"set-2"},{"id":"set2-UC3lvLR8","fingerprint":"aec94c669fd07198","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"Cum este descrisă orientarea traiectoriilor mișcărilor mandibulare la nivelul suprafețelor ocluzale (aspectul urmelor „degetelor de pasăre”)?","options":[{"id":"A","text":"Ansamblul traiectoriilor ocluzale reprezintă reproducerea mișcărilor mandibulare în plan orizontal, la scară mărită."},{"id":"B","text":"Traiectoriile protruzive au o direcție mezială la mandibulă și distală la maxilar."},{"id":"C","text":"Traiectoriile protruzive au o direcție distală la nivelul dinților mandibulari și spre mezial la maxilar."},{"id":"D","text":"Amprentele în formă de „degete de pasăre” sunt orientate posterior la nivelul dinților din arcada superioară."},{"id":"E","text":"Cuspidul de ghidaj trasează exclusiv aceste traiectorii pe suprafața ocluzală a dintelui omolog."}],"correct":["C"],"pages":[187],"source":"set-2"},{"id":"set2-MrnN32fs","fingerprint":"5c8d2cfc84d6a240","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele corelații privind influența parametrilor cinematici asupra morfologiei ocluzale sunt adevărate?","options":[{"id":"A","text":"O distanță intercondiliană mai mare determină un unghi mai mare între traiectoriile de laterotruzie și mediotruzie la nivel ocluzal."},{"id":"B","text":"O valoare mai mare a unghiului Bennett necesită o concavitate mai accentuată a fețelor palatinale ale frontalilor superiori."},{"id":"C","text":"Neregularitățile curbei transversale de ocluzie pot determina apariția interferențelor lucrătoare și nelucrătoare în mișcările de lateralitate."},{"id":"D","text":"Distanța intercondiliană exercită o influență asupra morfologiei ocluzale net superioară unghiului și mișcării Bennett."},{"id":"E","text":"Gradul de overbite și cel de overjet influențează direct proporțional morfologia suprafețelor ocluzale."}],"correct":["B","C"],"pages":[187],"source":"set-2"},{"id":"set2-uABEhtRL","fingerprint":"61f0cd9862c61509","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt afirmațiile adevărate privind caracteristicile și utilizarea articulatoarelor semiadaptabile de tip arcon și non-arcon?","options":[{"id":"A","text":"Denumirile de arcon și non-arcon au fost conferite de Gerber în anul 1950."},{"id":"B","text":"Utilizarea înregistrărilor poziționale în propulsie pentru programarea articulatorului non-arcon poate genera erori la nivel ocluzal."},{"id":"C","text":"La deschiderea articulatorului arcon, unghiul Balkwill rămâne nemodificat."},{"id":"D","text":"La articulatorul non-arcon, modificarea unghiului Balkwill la deschidere poate produce erori ocluzale predominante în zona incisivilor."},{"id":"E","text":"Ambele tipuri de articulatoare, în ciuda diferențelor constructive, oferă rezultate protetice aproape identice."}],"correct":["B","C","E"],"pages":[188],"source":"set-2"},{"id":"set2-C0s0lVyg","fingerprint":"14b60fe2ebb0cc92","chapterId":"set-2","subchapterId":"set2-3.01","type":"CS","text":"În cadrul reabilitărilor protetice de mare amploare realizate pe un ocludator simplu, care este consecința biomecanică principală generată de diferența dintre arcul de închidere al instrumentului și cel al mandibulei?","options":[{"id":"A","text":"Apariția contactelor premature predominant în zonele frontale pe parcursul mișcării de închidere."},{"id":"B","text":"Pivotarea superioară a condililor mandibulari din poziția stabilă ortopedic în vederea realizării intercuspidării maxime."},{"id":"C","text":"Generarea de contacte premature în zonele distale care determină pivotări inferioare ale condililor mandibulari sub acțiunea mușchilor ridicători."},{"id":"D","text":"Limitarea deplasărilor în plan frontal exclusiv la o anvelopă situată în afara poziției de postură a mandibulei."},{"id":"E","text":"Alterarea severă a unghiului Balkwill pe parcursul închiderii, cu formarea de supracontacte exclusiv la nivelul premolarilor."}],"correct":["C"],"pages":[187],"source":"set-2"},{"id":"set2-mvio5h1O","fingerprint":"a67f93c6138815e5","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Identificați afirmațiile adevărate referitoare la arcurile faciale de transfer și tipologia acestora:","options":[{"id":"A","text":"Arcurile cinematice determină poziția modelului maxilar exclusiv pe baza reperajului pretragian și a planului de la Frankfurt."},{"id":"B","text":"Arcul facial postural propus de Ferrarrio orientează tridimensional planul de ocluzie în poziția naturală a capului."},{"id":"C","text":"Arcurile faciale arbitrare se poziționează pe baza depistării axei balama reale a pacientului."},{"id":"D","text":"Arcul facial de tip Dentatus reprezintă un arc arbitrar cu fixare facială pretragiană."},{"id":"E","text":"Arcul facial cu fixare auriculară de tip FAG utilizează pentru poziționare localizarea arbitrară a axei balama terminale."}],"correct":["B","D","E"],"pages":[188],"source":"set-2"},{"id":"set2-L1Djhty6","fingerprint":"0d56f706b9bfbbb8","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care dintre următoarele reprezintă metode valide de programare a articulatoarelor conform cinematicii mandibulare a pacientului?","options":[{"id":"A","text":"Înregistrările grafice intraorale prin determinarea unghiului simfizar gotic."},{"id":"B","text":"Axiografia temporo-mandibulară utilizată exclusiv pentru evaluarea unghiului Balkwill și a axei balama terminale."},{"id":"C","text":"Axiografia mecanică sau electronică pentru înregistrarea tiparului traseului condililor mandibulari nelucrători în lateralitate."},{"id":"D","text":"Aprecierea directă in vivo a poziției tridimensionale a planului de ocluzie utilizând condylatorul lui Gerber."},{"id":"E","text":"Înregistrările poziționale ale mandibulei în intercuspidare maximă, propulsie și lateralitate, realizate cu sau fără contactare dento-dentară."}],"correct":["A","C","E"],"pages":[188],"source":"set-2"},{"id":"set2-O-IuNwN6","fingerprint":"a4dbd35d8e033a02","chapterId":"set-2","subchapterId":"set2-3.01","type":"CM","text":"Care sunt afirmațiile adevărate cu privire la reperele anatomice și structural-funcționale implicate în fixarea arcurilor faciale?","options":[{"id":"A","text":"Arcurile faciale fixate auricular posedă un punct de sprijin glabelar situat la nivelul nasionului."},{"id":"B","text":"Arcul facial al condylatorului Gerber constituie un exemplu reprezentativ de instrument fixat exclusiv pe arcada maxilară."},{"id":"C","text":"Toate arcurile faciale se fixează exclusiv pe arcada maxilară, aceasta fiind o condiție absolută pentru un transfer funcțional."},{"id":"D","text":"Fixarea pretragiană a arcului facial se realizează la o distanță de 10-13 mm pe linia care unește tragusul cu punctul infraorbital."},{"id":"E","text":"Existența punctului de sprijin glabelar are rolul de a plasa brațele laterale ale arcului la nivelul planului de la Frankfurt."}],"correct":["A","D","E"],"pages":[188],"source":"set-2"}];
